async function STUFF(src, dest, max = 29) {
  let ptr = P_LEXSTART, ctr = 1, bptr = 0;
  putb(dest, 0, getb(src, 0));
  putb(dest, 1, getb(src, 1));
  for (;;) {
    put(dest, ptr, get(src, ptr));
    bptr = (ptr * 2) + 2;
    putb(dest, bptr, getb(src, bptr));
    bptr = (ptr * 2) + 3;
    putb(dest, bptr, getb(src, bptr));
    ptr = ptr + P_LEXELEN;
    if (++ctr > max) {
      return true;
    }
  }
}

async function INBUF_STUFF(src, dest) {
  let cnt = 0;
  cnt = getb(src, 0) - 1;
  for (;;) {
    putb(dest, cnt, getb(src, cnt));
    if (--cnt < 0) {
      return true;
    }
  }
}

async function INBUF_ADD(len, beg, slot) {
  let dbeg = 0, ctr = 0, tmp = 0;
  if (tmp = get(g.OOPS_TABLE, O_END)) {
    dbeg = tmp;
  } else {
    dbeg = getb(g.AGAIN_LEXV, tmp = get(g.OOPS_TABLE, O_LENGTH)) + getb(g.AGAIN_LEXV, tmp + 1);
  }
  put(g.OOPS_TABLE, O_END, dbeg + len);
  loop1: for (;;) {
    putb(g.OOPS_INBUF, dbeg + ctr, getb(g.P_INBUF, beg + ctr));
    ctr = ctr + 1;
    if (ctr == len) {
      break loop1;
    }
  }
  putb(g.AGAIN_LEXV, slot, dbeg);
  return putb(g.AGAIN_LEXV, slot - 1, len);
}

async function WT$(ptr, bit, b1 = 5) {
  let offs = P_P1OFF, typ = 0;
  if (btst(typ = getb(ptr, P_PSOFF), bit)) {
    if (b1 > 4) {
      return true;
    } else {
      typ = typ & P_P1BITS;
      if (!(typ == b1)) {
        offs = offs + 1;
      }
      return getb(ptr, offs);
    }
  } else {
    return false;
  }
}

async function CLAUSE(ptr, val, wrd) {
  let off = 0, num = 0, andflg = false, first$$ = true, nw = 0, lw = 0;
  off = (g.P_NCN - 1) * 2;
  if (!(val == 0)) {
    put(g.P_ITBL, num = P_PREP1 + off, val);
    put(g.P_ITBL, num + 1, wrd);
    ptr = ptr + P_LEXELEN;
  } else {
    g.P_LEN = g.P_LEN + 1;
  }
  if (g.P_LEN == 0) {
    g.P_NCN = g.P_NCN - 1;
    return -1;
  }
  put(g.P_ITBL, num = P_NC1 + off, g.P_LEXV + (ptr * 2));
  if (eq(get(g.P_LEXV, ptr), W.THE, W.A, W.AN)) {
    put(g.P_ITBL, num, get(g.P_ITBL, num) + 4);
  }
  for (;;) {
    if ((g.P_LEN = g.P_LEN - 1) < 0) {
      put(g.P_ITBL, num + 1, g.P_LEXV + (ptr * 2));
      return -1;
    }
    if ((wrd = get(g.P_LEXV, ptr)) || (wrd = await NUMBER$(ptr))) {
      if (g.P_LEN == 0) {
        nw = 0;
      } else {
        nw = get(g.P_LEXV, ptr + P_LEXELEN);
      }
      if (wrd == W.AND || wrd == W.COMMA) {
        andflg = true;
      } else if (wrd == W.ALL || wrd == W.ONE || wrd == W.BOTH) {
        if (nw == W.OF) {
          g.P_LEN = g.P_LEN - 1;
          ptr = ptr + P_LEXELEN;
        }
      } else if ((wrd == W.THEN || wrd == W.PERIOD) || ((await WT$(wrd, PS$PREPOSITION)) && get(g.P_ITBL, P_VERB) && !first$$)) {
        g.P_LEN = g.P_LEN + 1;
        put(g.P_ITBL, num + 1, g.P_LEXV + (ptr * 2));
        return ptr - P_LEXELEN;
      } else if (await WT$(wrd, PS$OBJECT)) {
        if ((g.P_LEN > 0) && (nw == W.OF) && !(wrd == W.ALL || wrd == W.ONE)) {
        } else if ((await WT$(wrd, PS$ADJECTIVE, P1$ADJECTIVE)) && !(nw == 0) && (await WT$(nw, PS$OBJECT))) {
        } else if (!andflg && !(nw == W.BUT || nw == W.EXCEPT) && !(nw == W.AND || nw == W.COMMA)) {
          put(g.P_ITBL, num + 1, g.P_LEXV + ((ptr + 2) * 2));
          return ptr;
        } else {
          andflg = false;
        }
      } else if ((g.P_MERGED || g.P_OFLAG || !(eq(get(g.P_ITBL, P_VERB), 0))) && ((await WT$(wrd, PS$ADJECTIVE)) || (await WT$(wrd, PS$BUZZ_WORD)))) {
      } else if (andflg && (eq(get(g.P_ITBL, P_VERB), 0) || (await WT$(wrd, PS$DIRECTION)) || (await WT$(wrd, PS$VERB)))) {
        ptr = ptr - 4;
        put(g.P_LEXV, ptr + 2, W.THEN);
        g.P_LEN = g.P_LEN + 2;
      } else if (await WT$(wrd, PS$PREPOSITION)) {
      } else {
        await CANT_USE(ptr);
        return false;
      }
    } else {
      await UNKNOWN_WORD(ptr);
      return false;
    }
    lw = wrd;
    first$$ = false;
    ptr = ptr + P_LEXELEN;
  }
}

async function NUMBER$(ptr) {
  let cnt = 0, bptr = 0, chr = 0, sum = 0, tim = false;
  cnt = getb(g.P_LEXV + (ptr * 2), 2);
  bptr = getb(g.P_LEXV + (ptr * 2), 3);
  loop1: for (;;) {
    if ((cnt = cnt - 1) < 0) {
      break loop1;
    } else {
      chr = getb(g.P_INBUF, bptr);
      if (chr == 58) {
        tim = sum;
        sum = 0;
      } else if (sum > 10000) {
        return false;
      } else if ((chr < 58) && (chr > 47)) {
        sum = (sum * 10) + (chr - 48);
      } else {
        return false;
      }
      bptr = bptr + 1;
    }
  }
  put(g.P_LEXV, ptr, W.INTNUM);
  if (sum > 1000) {
    return false;
  } else if (tim) {
    if (tim < 8) {
      tim = tim + 12;
    } else if (tim > 23) {
      return false;
    }
    sum = sum + (tim * 60);
  }
  g.P_NUMBER = sum;
  return W.INTNUM;
}

async function ORPHAN_MERGE() {
  let cnt = (-1), temp = 0, verb = 0, beg = 0, end = 0, adj = false, wrd = 0;
  g.P_OFLAG = false;
  if (eq(await WT$(wrd = get(get(g.P_ITBL, P_VERBN), 0), PS$VERB, P1$VERB), get(g.P_OTBL, P_VERB)) || !((await WT$(wrd, PS$ADJECTIVE)) == 0)) {
    adj = true;
  } else if (!((await WT$(wrd, PS$OBJECT, P1$OBJECT)) == 0) && (g.P_NCN == 0)) {
    put(g.P_ITBL, P_VERB, 0);
    put(g.P_ITBL, P_VERBN, 0);
    put(g.P_ITBL, P_NC1, g.P_LEXV + 2);
    put(g.P_ITBL, P_NC1L, g.P_LEXV + 6);
    g.P_NCN = 1;
  }
  if (!((verb = get(g.P_ITBL, P_VERB)) == 0) && !adj && !(verb == get(g.P_OTBL, P_VERB))) {
    return false;
  } else if (g.P_NCN == 2) {
    return false;
  } else if (eq(get(g.P_OTBL, P_NC1), 1)) {
    if (eq(temp = get(g.P_ITBL, P_PREP1), get(g.P_OTBL, P_PREP1)) || (temp == 0)) {
      if (adj) {
        put(g.P_OTBL, P_NC1, g.P_LEXV + 2);
        if (get(g.P_ITBL, P_NC1L) == 0) {
          put(g.P_ITBL, P_NC1L, g.P_LEXV + 6);
        }
        if (g.P_NCN == 0) {
          g.P_NCN = 1;
        }
      } else {
        put(g.P_OTBL, P_NC1, get(g.P_ITBL, P_NC1));
      }
      put(g.P_OTBL, P_NC1L, get(g.P_ITBL, P_NC1L));
    } else {
      return false;
    }
  } else if (eq(get(g.P_OTBL, P_NC2), 1)) {
    if (eq(temp = get(g.P_ITBL, P_PREP1), get(g.P_OTBL, P_PREP2)) || (temp == 0)) {
      if (adj) {
        put(g.P_ITBL, P_NC1, g.P_LEXV + 2);
        if (get(g.P_ITBL, P_NC1L) == 0) {
          put(g.P_ITBL, P_NC1L, g.P_LEXV + 6);
        }
      }
      put(g.P_OTBL, P_NC2, get(g.P_ITBL, P_NC1));
      put(g.P_OTBL, P_NC2L, get(g.P_ITBL, P_NC1L));
      g.P_NCN = 2;
    } else {
      return false;
    }
  } else if (!(g.P_ACLAUSE == 0)) {
    if (!(g.P_NCN == 1) && !adj) {
      g.P_ACLAUSE = false;
      return false;
    } else {
      beg = get(g.P_ITBL, P_NC1);
      if (adj) {
        beg = g.P_LEXV + 2;
        adj = false;
      }
      end = get(g.P_ITBL, P_NC1L);
      loop1: for (;;) {
        wrd = get(beg, 0);
        if (beg == end) {
          if (adj) {
            await ACLAUSE_WIN(adj);
            break loop1;
          } else {
            g.P_ACLAUSE = false;
            return false;
          }
        } else if (!adj && (btst(getb(wrd, P_PSOFF), PS$ADJECTIVE) || (wrd == W.ALL || wrd == W.ONE))) {
          adj = wrd;
        } else if (wrd == W.ONE) {
          await ACLAUSE_WIN(adj);
          break loop1;
        } else if (btst(getb(wrd, P_PSOFF), PS$OBJECT)) {
          if (wrd == g.P_ANAM) {
            await ACLAUSE_WIN(adj);
          } else {
            await NCLAUSE_WIN();
          }
          break loop1;
        }
        beg = beg + P_WORDLEN;
        if (end == 0) {
          end = beg;
          g.P_NCN = 1;
          put(g.P_ITBL, P_NC1, beg - 4);
          put(g.P_ITBL, P_NC1L, beg);
        }
      }
    }
  }
  put(g.P_VTBL, 0, get(g.P_OVTBL, 0));
  putb(g.P_VTBL, 2, getb(g.P_OVTBL, 2));
  putb(g.P_VTBL, 3, getb(g.P_OVTBL, 3));
  put(g.P_OTBL, P_VERBN, g.P_VTBL);
  putb(g.P_VTBL, 2, 0);
  for (;;) {
    if ((cnt = cnt + 1) > P_ITBLLEN) {
      g.P_MERGED = true;
      return true;
    } else {
      put(g.P_ITBL, cnt, get(g.P_OTBL, cnt));
    }
  }
  return true;
}

async function ACLAUSE_WIN(adj) {
  put(g.P_ITBL, P_VERB, get(g.P_OTBL, P_VERB));
  put(g.P_CCTBL, CC_SBPTR, g.P_ACLAUSE);
  put(g.P_CCTBL, CC_SEPTR, g.P_ACLAUSE + 1);
  put(g.P_CCTBL, CC_DBPTR, g.P_ACLAUSE);
  put(g.P_CCTBL, CC_DEPTR, g.P_ACLAUSE + 1);
  await CLAUSE_COPY(g.P_OTBL, g.P_OTBL, adj);
  !(eq(get(g.P_OTBL, P_NC2), 0)) && (g.P_NCN = 2);
  g.P_ACLAUSE = false;
  return true;
}

async function NCLAUSE_WIN() {
  put(g.P_CCTBL, CC_SBPTR, P_NC1);
  put(g.P_CCTBL, CC_SEPTR, P_NC1L);
  put(g.P_CCTBL, CC_DBPTR, g.P_ACLAUSE);
  put(g.P_CCTBL, CC_DEPTR, g.P_ACLAUSE + 1);
  await CLAUSE_COPY(g.P_ITBL, g.P_OTBL);
  !(eq(get(g.P_OTBL, P_NC2), 0)) && (g.P_NCN = 2);
  g.P_ACLAUSE = false;
  return true;
}

async function WORD_PRINT(cnt, buf) {
  for (;;) {
    if (--cnt < 0) {
      return true;
    } else {
      printC(getb(g.P_INBUF, buf));
      buf = buf + 1;
    }
  }
}

async function UNKNOWN_WORD(ptr) {
  let buf = 0;
  put(g.OOPS_TABLE, O_PTR, ptr);
  if (isVerb(V.SAY)) {
    tell("Nothing happens.\n");
    return false;
  }
  tell("I don't know the word \"");
  await WORD_PRINT(getb(g.P_LEXV + (buf = ptr * 2), 2), getb(g.P_LEXV + buf, 3));
  tell("\".\n");
  g.QUOTE_FLAG = false;
  return g.P_OFLAG = false;
}

async function CANT_USE(ptr) {
  let buf = 0;
  if (isVerb(V.SAY)) {
    tell("Nothing happens.\n");
    return false;
  }
  tell("You used the word \"");
  await WORD_PRINT(getb(g.P_LEXV + (buf = ptr * 2), 2), getb(g.P_LEXV + buf, 3));
  tell("\" in a way that I don't understand.\n");
  g.QUOTE_FLAG = false;
  return g.P_OFLAG = false;
}

async function SYNTAX_CHECK() {
  let syn = 0, len = 0, num = 0, obj = 0, drive1 = false, drive2 = false, prep = 0, verb = 0, tmp = 0;
  if ((verb = get(g.P_ITBL, P_VERB)) == 0) {
    tell("There was no verb in that sentence!\n");
    return false;
  }
  syn = get(g.VERBS, 255 - verb);
  len = getb(syn, 0);
  syn = syn + 1;
  loop1: for (;;) {
    num = getb(syn, P_SBITS) & P_SONUMS;
    if (g.P_NCN > num) {
    } else if (!(num < 1) && (g.P_NCN == 0) && (((prep = get(g.P_ITBL, P_PREP1)) == 0) || (prep == getb(syn, P_SPREP1)))) {
      drive1 = syn;
    } else if (eq(getb(syn, P_SPREP1), get(g.P_ITBL, P_PREP1))) {
      if ((num == 2) && (g.P_NCN == 1)) {
        drive2 = syn;
      } else if (eq(getb(syn, P_SPREP2), get(g.P_ITBL, P_PREP2))) {
        await SYNTAX_FOUND(syn);
        return true;
      }
    }
    if (--len < 1) {
      if (drive1 || drive2) {
        break loop1;
      } else {
        tell("That sentence isn't one I recognize.\n");
        return false;
      }
    } else {
      syn = syn + P_SYNLEN;
    }
  }
  if (drive1 && (obj = await GWIM(getb(drive1, P_SFWIM1), getb(drive1, P_SLOC1), getb(drive1, P_SPREP1)))) {
    put(g.P_PRSO, g.P_MATCHLEN, 1);
    put(g.P_PRSO, 1, obj);
    return await SYNTAX_FOUND(drive1);
  } else if (drive2 && (obj = await GWIM(getb(drive2, P_SFWIM2), getb(drive2, P_SLOC2), getb(drive2, P_SPREP2)))) {
    put(g.P_PRSI, g.P_MATCHLEN, 1);
    put(g.P_PRSI, 1, obj);
    return await SYNTAX_FOUND(drive2);
  } else if (verb == ACT.FIND) {
    tell("That question can't be answered.\n");
    return false;
  } else if (!(g.WINNER == g.PLAYER)) {
    return await CANT_ORPHAN();
  } else {
    await ORPHAN(drive1, drive2);
    tell("What do you want to ");
    tmp = get(g.P_OTBL, P_VERBN);
    if (tmp == 0) {
      tell("tell");
    } else if (getb(g.P_VTBL, 2) == 0) {
      printB(get(tmp, 0));
    } else {
      await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
      putb(g.P_VTBL, 2, 0);
    }
    if (drive2) {
      tell(" ");
      await THING_PRINT(true, true);
    }
    g.P_OFLAG = true;
    await PREP_PRINT(drive1 ? getb(drive1, P_SPREP1) : getb(drive2, P_SPREP2));
    tell("?\n");
    return false;
  }
}

async function CANT_ORPHAN() {
  tell("\"I don't understand! What are you referring to?\"\n");
  return false;
}

async function ORPHAN(d1, d2) {
  let cnt = (-1);
  if (!g.P_MERGED) {
    put(g.P_OCLAUSE, g.P_MATCHLEN, 0);
  }
  put(g.P_OVTBL, 0, get(g.P_VTBL, 0));
  putb(g.P_OVTBL, 2, getb(g.P_VTBL, 2));
  putb(g.P_OVTBL, 3, getb(g.P_VTBL, 3));
  loop1: for (;;) {
    if (++cnt > P_ITBLLEN) {
      break loop1;
    } else {
      put(g.P_OTBL, cnt, get(g.P_ITBL, cnt));
    }
  }
  if (g.P_NCN == 2) {
    put(g.P_CCTBL, CC_SBPTR, P_NC2);
    put(g.P_CCTBL, CC_SEPTR, P_NC2L);
    put(g.P_CCTBL, CC_DBPTR, P_NC2);
    put(g.P_CCTBL, CC_DEPTR, P_NC2L);
    await CLAUSE_COPY(g.P_ITBL, g.P_OTBL);
  }
  if (!(g.P_NCN < 1)) {
    put(g.P_CCTBL, CC_SBPTR, P_NC1);
    put(g.P_CCTBL, CC_SEPTR, P_NC1L);
    put(g.P_CCTBL, CC_DBPTR, P_NC1);
    put(g.P_CCTBL, CC_DEPTR, P_NC1L);
    await CLAUSE_COPY(g.P_ITBL, g.P_OTBL);
  }
  if (d1) {
    put(g.P_OTBL, P_PREP1, getb(d1, P_SPREP1));
    return put(g.P_OTBL, P_NC1, 1);
  } else if (d2) {
    put(g.P_OTBL, P_PREP2, getb(d2, P_SPREP2));
    return put(g.P_OTBL, P_NC2, 1);
  } else {
    return false;
  }
}

async function THING_PRINT(prso$, the$ = false) {
  let beg = 0, end = 0;
  if (prso$) {
    beg = get(g.P_ITBL, P_NC1);
    end = get(g.P_ITBL, P_NC1L);
  } else {
    beg = get(g.P_ITBL, P_NC2);
    end = get(g.P_ITBL, P_NC2L);
  }
  return await BUFFER_PRINT(beg, end, the$);
}

async function BUFFER_PRINT(beg, end, cp) {
  let nosp = true, wrd = 0, first$$ = true, pn = false, q$ = false;
  for (;;) {
    if (beg == end) {
      return true;
    } else {
      wrd = get(beg, 0);
      if (wrd == W.COMMA) {
        tell(", ");
      } else if (nosp) {
        nosp = false;
      } else {
        tell(" ");
      }
      if (wrd == W.PERIOD || wrd == W.COMMA) {
        nosp = true;
      } else if (wrd == W.ME) {
        printD(ME);
        pn = true;
      } else if (wrd == W.INTNUM) {
        printN(g.P_NUMBER);
        pn = true;
      } else {
        if (first$$ && !pn && cp) {
          tell("the ");
        }
        if (g.P_OFLAG || g.P_MERGED) {
          printB(wrd);
        } else if ((wrd == W.IT) && (await ACCESSIBLE$(g.P_IT_OBJECT))) {
          printD(g.P_IT_OBJECT);
        } else {
          await WORD_PRINT(getb(beg, 2), getb(beg, 3));
        }
        first$$ = false;
      }
    }
    beg = beg + P_WORDLEN;
  }
}

async function PREP_PRINT(prep) {
  let wrd = 0;
  if (!(prep == 0)) {
    tell(" ");
    if (prep == PR.THROUGH) {
      tell("through");
      return true;
    } else {
      wrd = await PREP_FIND(prep);
      return printB(wrd);
    }
  } else {
    return false;
  }
}

async function CLAUSE_COPY(src, dest, insrt = false) {
  let beg = 0, end = 0;
  beg = get(src, get(g.P_CCTBL, CC_SBPTR));
  end = get(src, get(g.P_CCTBL, CC_SEPTR));
  put(dest, get(g.P_CCTBL, CC_DBPTR), g.P_OCLAUSE + ((get(g.P_OCLAUSE, g.P_MATCHLEN) * P_LEXELEN) + 2));
  for (;;) {
    if (beg == end) {
      put(dest, get(g.P_CCTBL, CC_DEPTR), g.P_OCLAUSE + ((get(g.P_OCLAUSE, g.P_MATCHLEN) * P_LEXELEN) + 2));
      return true;
    } else {
      if (insrt && (g.P_ANAM == get(beg, 0))) {
        await CLAUSE_ADD(insrt);
      }
      await CLAUSE_ADD(get(beg, 0));
    }
    beg = beg + P_WORDLEN;
  }
}

async function CLAUSE_ADD(wrd) {
  let ptr = 0;
  ptr = get(g.P_OCLAUSE, g.P_MATCHLEN) + 2;
  put(g.P_OCLAUSE, ptr - 1, wrd);
  put(g.P_OCLAUSE, ptr, 0);
  return put(g.P_OCLAUSE, g.P_MATCHLEN, ptr);
}

async function PREP_FIND(prep) {
  let cnt = 0, size = 0;
  size = get(g.PREPOSITIONS, 0) * 2;
  for (;;) {
    if (++cnt > size) {
      return false;
    } else if (eq(get(g.PREPOSITIONS, cnt), prep)) {
      return get(g.PREPOSITIONS, cnt - 1);
    }
  }
}

async function SYNTAX_FOUND(syn) {
  g.P_SYNTAX = syn;
  return g.PRSA = getb(syn, P_SACTION);
}

async function GWIM(gbit, lbit, prep) {
  let obj = 0;
  if (gbit == RLANDBIT) {
    return ROOMS;
  }
  g.P_GWIMBIT = gbit;
  g.P_SLOCBITS = lbit;
  put(g.P_MERGE, g.P_MATCHLEN, 0);
  if (await GET_OBJECT(g.P_MERGE, false)) {
    g.P_GWIMBIT = 0;
    if (eq(get(g.P_MERGE, g.P_MATCHLEN), 1)) {
      obj = get(g.P_MERGE, 1);
      tell("(");
      if (!(prep == 0) && !g.P_END_ON_PREP) {
        printB(prep = await PREP_FIND(prep));
        if (prep == W.OUT) {
          tell(" of");
        }
        tell(" ");
        if (obj == HANDS) {
          tell("your hands");
        } else {
          tell("the ", D(obj));
        }
        tell(")\n");
      } else {
        tell(D(obj), ")\n");
      }
      return obj;
    } else {
      return false;
    }
  } else {
    g.P_GWIMBIT = 0;
    return false;
  }
}

async function SNARF_OBJECTS() {
  let optr = 0, iptr = 0, l = 0;
  let $1, $2;
  put(g.P_BUTS, g.P_MATCHLEN, 0);
  if (!(eq(iptr = get(g.P_ITBL, P_NC2), 0))) {
    g.P_SLOCBITS = getb(g.P_SYNTAX, P_SLOC2);
    $1 = await SNARFEM(iptr, get(g.P_ITBL, P_NC2L), g.P_PRSI);
    if (!$1) {
      return false;
    }
  }
  if (!(eq(optr = get(g.P_ITBL, P_NC1), 0))) {
    g.P_SLOCBITS = getb(g.P_SYNTAX, P_SLOC1);
    $2 = await SNARFEM(optr, get(g.P_ITBL, P_NC1L), g.P_PRSO);
    if (!$2) {
      return false;
    }
  }
  if (!(get(g.P_BUTS, g.P_MATCHLEN) == 0)) {
    l = get(g.P_PRSO, g.P_MATCHLEN);
    if (optr) {
      g.P_PRSO = await BUT_MERGE(g.P_PRSO);
    }
    if (iptr && (!optr || (l == get(g.P_PRSO, g.P_MATCHLEN)))) {
      g.P_PRSI = await BUT_MERGE(g.P_PRSI);
    }
  }
  return true;
}

async function BUT_MERGE(tbl) {
  let len = 0, butlen = 0, cnt = 1, matches = 0, obj = 0, ntbl = 0;
  len = get(tbl, g.P_MATCHLEN);
  put(g.P_MERGE, g.P_MATCHLEN, 0);
  loop1: for (;;) {
    if (--len < 0) {
      break loop1;
    } else if (await ZMEMQ(obj = get(tbl, cnt), g.P_BUTS)) {
    } else {
      put(g.P_MERGE, matches + 1, obj);
      matches = matches + 1;
    }
    cnt = cnt + 1;
  }
  put(g.P_MERGE, g.P_MATCHLEN, matches);
  ntbl = g.P_MERGE;
  g.P_MERGE = tbl;
  return ntbl;
}

async function SNARFEM(ptr, eptr, tbl) {
  let but = false, len = 0, wv = 0, wrd = 0, nw = 0, was_all = false;
  let $1, $2, $3, $4;
  g.P_AND = false;
  if (g.P_GETFLAGS == P_ALL) {
    was_all = true;
  }
  g.P_GETFLAGS = 0;
  put(tbl, g.P_MATCHLEN, 0);
  wrd = get(ptr, 0);
  for (;;) {
    if (ptr == eptr) {
      wv = await GET_OBJECT(but || tbl);
      if (was_all) {
        g.P_GETFLAGS = P_ALL;
      }
      return wv;
    } else {
      if (eptr == (ptr + P_WORDLEN)) {
        nw = 0;
      } else {
        nw = get(ptr, P_LEXELEN);
      }
      if (wrd == W.ALL || wrd == W.BOTH) {
        g.P_GETFLAGS = P_ALL;
        if (nw == W.OF) {
          ptr = ptr + P_WORDLEN;
        }
      } else if (wrd == W.BUT || wrd == W.EXCEPT) {
        $1 = await GET_OBJECT(but || tbl);
        if (!$1) {
          return false;
        }
        but = g.P_BUTS;
        put(but, g.P_MATCHLEN, 0);
      } else if (wrd == W.A || wrd == W.ONE) {
        if (!g.P_ADJ) {
          g.P_GETFLAGS = P_ONE;
          if (nw == W.OF) {
            ptr = ptr + P_WORDLEN;
          }
        } else {
          g.P_NAM = g.P_ONEOBJ;
          $2 = await GET_OBJECT(but || tbl);
          if (!$2) {
            return false;
          }
          $3 = nw == 0;
          if ($3) {
            return true;
          }
        }
      } else if ((wrd == W.AND || wrd == W.COMMA) && !(nw == W.AND || nw == W.COMMA)) {
        g.P_AND = true;
        $4 = await GET_OBJECT(but || tbl);
        if (!$4) {
          return false;
        }
      } else if (await WT$(wrd, PS$BUZZ_WORD)) {
      } else if (wrd == W.AND || wrd == W.COMMA) {
      } else if (wrd == W.OF) {
        if (g.P_GETFLAGS == 0) {
          g.P_GETFLAGS = P_INHIBIT;
        }
      } else if ((wv = await WT$(wrd, PS$ADJECTIVE, P1$ADJECTIVE)) && (await ADJ_CHECK(wrd))) {
        g.P_ADJ = wv;
        g.P_ADJN = wrd;
      } else if (await WT$(wrd, PS$OBJECT, P1$OBJECT)) {
        g.P_NAM = wrd;
        g.P_ONEOBJ = wrd;
      }
    }
    if (!(ptr == eptr)) {
      ptr = ptr + P_WORDLEN;
      wrd = nw;
    }
  }
}

async function ADJ_CHECK(wrd) {
  if (g.P_ADJ && ((wrd == W.ENCHAN || wrd == W.SPELL || wrd == W.CASTLE) || (wrd == W.RIVER))) {
    return false;
  } else if (!g.P_ADJ) {
    return true;
  } else if (g.P_ADJ == A.UPPER || g.P_ADJ == A.LOWER) {
    return false;
  } else {
    return true;
  }
}

async function GET_OBJECT(tbl, vrb = true) {
  let bits = 0, len = 0, xbits = 0, tlen = 0, gcheck = false, olen = 0, obj = 0;
  xbits = g.P_SLOCBITS;
  tlen = get(tbl, g.P_MATCHLEN);
  if (btst(g.P_GETFLAGS, P_INHIBIT)) {
    return true;
  }
  if (!g.P_NAM && g.P_ADJ) {
    if (await WT$(g.P_ADJN, PS$OBJECT, P1$OBJECT)) {
      g.P_NAM = g.P_ADJN;
      g.P_ADJ = false;
    } else if (await NULL_F()) {
    }
  }
  if (!g.P_NAM && !g.P_ADJ && !(g.P_GETFLAGS == P_ALL) && (g.P_GWIMBIT == 0)) {
    if (vrb) {
      tell("There seems to be a noun missing in that sentence!\n");
    }
    return false;
  }
  if (!(g.P_GETFLAGS == P_ALL) || (g.P_SLOCBITS == 0)) {
    g.P_SLOCBITS = -1;
  }
  g.P_TABLE = tbl;
  loop1: for (;;) {
    if (gcheck) {
      await GLOBAL_CHECK(tbl);
    } else {
      if (g.LIT || g.BLORTED) {
        clearFlag(g.PLAYER, TRANSBIT);
        await DO_SL(g.HERE, SOG, SIR);
        setFlag(g.PLAYER, TRANSBIT);
      }
      await DO_SL(g.PLAYER, SH, SC);
      if (eq(get(tbl, 0), tlen)) {
        if (g.P_ADJ && (g.P_NAM == W.SPELL || g.P_NAM == false)) {
          g.P_NAM = g.P_ADJN;
        }
        await SPELL_CHECK(tbl, g.P_NAM);
      }
    }
    len = get(tbl, g.P_MATCHLEN) - tlen;
    if (btst(g.P_GETFLAGS, P_ALL)) {
    } else if (btst(g.P_GETFLAGS, P_ONE) && !(len == 0)) {
      if (!(len == 1)) {
        put(tbl, 1, get(tbl, random(len)));
        tell("(How about the ");
        printD(get(tbl, 1));
        tell("?)\n");
      }
      put(tbl, g.P_MATCHLEN, 1);
    } else if ((len > 1) || ((len == 0) && !(g.P_SLOCBITS == (-1)))) {
      if (g.P_SLOCBITS == (-1)) {
        g.P_SLOCBITS = xbits;
        olen = len;
        put(tbl, g.P_MATCHLEN, get(tbl, g.P_MATCHLEN) - len);
        continue loop1;
      } else {
        if (len == 0) {
          len = olen;
        }
        if (!(g.WINNER == g.PLAYER)) {
          await CANT_ORPHAN();
          return false;
        } else if (vrb && g.P_NAM) {
          await WHICH_PRINT(tlen, len, tbl);
          g.P_ACLAUSE = tbl == g.P_PRSO ? P_NC1 : P_NC2;
          g.P_AADJ = g.P_ADJ;
          g.P_ANAM = g.P_NAM;
          await ORPHAN(false, false);
          g.P_OFLAG = true;
        } else if (vrb) {
          tell("There seems to be a noun missing in that sentence!\n");
        }
        g.P_NAM = false;
        g.P_ADJ = false;
        return false;
      }
    }
    if ((len == 0) && gcheck) {
      if (vrb) {
        g.P_SLOCBITS = xbits;
        if (g.LIT || g.BLORTED || isVerb(V.TELL, V.WHERE, V.WHAT, V.WHO, V.FROTZ)) {
          await OBJ_FOUND(NOT_HERE_OBJECT, tbl);
          g.P_XNAM = g.P_NAM;
          g.P_XADJ = g.P_ADJ;
          g.P_XADJN = g.P_ADJN;
          g.P_NAM = false;
          g.P_ADJ = false;
          g.P_ADJN = false;
          return true;
        } else {
          tell("It's too dark to see!\n");
        }
      }
      g.P_NAM = false;
      g.P_ADJ = false;
      return false;
    } else if (len == 0) {
      gcheck = true;
      continue loop1;
    }
    g.P_SLOCBITS = xbits;
    g.P_NAM = false;
    g.P_ADJ = false;
    return true;
  }
}

async function MOBY_FIND(tbl) {
  let foo = 0, len = 0;
  g.P_MOBY_FLAG = true;
  g.P_SLOCBITS = -1;
  g.P_TABLE = tbl;
  g.P_NAM = g.P_XNAM;
  g.P_ADJ = g.P_XADJ;
  put(tbl, g.P_MATCHLEN, 0);
  foo = first(ROOMS);
  loop1: for (;;) {
    if (!foo) {
      break loop1;
    } else {
      await SEARCH_LIST(foo, tbl, P_SRCALL);
      foo = next(foo);
    }
  }
  if (eq(len = get(tbl, g.P_MATCHLEN), 0)) {
    await DO_SL(LOCAL_GLOBALS, 1, 1);
  }
  if (eq(len = get(tbl, g.P_MATCHLEN), 0)) {
    await DO_SL(ROOMS, 1, 1);
  }
  if (eq(len = get(tbl, g.P_MATCHLEN), 1)) {
    g.P_MOBY_FOUND = get(tbl, 1);
  }
  g.P_MOBY_FLAG = false;
  g.P_NAM = false;
  g.P_ADJ = false;
  return len;
}

async function WHICH_PRINT(tlen, len, tbl) {
  let obj = 0, rlen = 0;
  rlen = len;
  tell("Which ");
  if (g.P_OFLAG || g.P_MERGED || g.P_AND) {
    printB(g.P_NAM ? g.P_NAM : (g.P_ADJ ? g.P_ADJN : W.ONE));
  } else {
    await THING_PRINT(tbl == g.P_PRSO);
  }
  tell(" do you mean, ");
  for (;;) {
    tlen = tlen + 1;
    obj = get(tbl, tlen);
    tell("the ", D(obj));
    if (len == 2) {
      if (!(rlen == 2)) {
        tell(",");
      }
      tell(" or ");
    } else if (len > 2) {
      tell(", ");
    }
    if ((len = len - 1) < 1) {
      tell("?\n");
      return true;
    }
  }
}

async function GLOBAL_CHECK(tbl) {
  let len = 0, rmg = 0, rmgl = 0, cnt = 0, obj = 0, obits = 0, foo = 0;
  len = get(tbl, g.P_MATCHLEN);
  obits = g.P_SLOCBITS;
  if (rmg = getPropAddr(g.HERE, P.GLOBAL)) {
    rmgl = propSize(rmg) - 1;
    loop1: for (;;) {
      if (await THIS_IT$(obj = getb(rmg, cnt), tbl)) {
        await OBJ_FOUND(obj, tbl);
      }
      if (++cnt > rmgl) {
        break loop1;
      }
    }
  }
  if (rmg = getPropAddr(g.HERE, P.PSEUDO)) {
    rmgl = div(propSize(rmg), 4) - 1;
    cnt = 0;
    loop2: for (;;) {
      if (g.P_NAM == get(rmg, cnt * 2)) {
        g.LAST_PSEUDO_LOC = g.HERE;
        putProp(PSEUDO_OBJECT, P.ACTION, get(rmg, (cnt * 2) + 1));
        foo = getPropAddr(PSEUDO_OBJECT, P.ACTION) - 5;
        put(foo, 0, get(g.P_NAM, 0));
        put(foo, 1, get(g.P_NAM, 1));
        await OBJ_FOUND(PSEUDO_OBJECT, tbl);
        break loop2;
      } else if (++cnt > rmgl) {
        break loop2;
      }
    }
  }
  if (eq(get(tbl, g.P_MATCHLEN), len)) {
    g.P_SLOCBITS = -1;
    g.P_TABLE = tbl;
    await DO_SL(GLOBAL_OBJECTS, 1, 1);
    return g.P_SLOCBITS = obits;
  } else {
    return false;
  }
}

async function DO_SL(obj, bit1, bit2) {
  let bts = 0;
  if (btst(g.P_SLOCBITS, bit1 + bit2)) {
    return await SEARCH_LIST(obj, g.P_TABLE, P_SRCALL);
  } else {
    if (btst(g.P_SLOCBITS, bit1)) {
      return await SEARCH_LIST(obj, g.P_TABLE, P_SRCTOP);
    } else if (btst(g.P_SLOCBITS, bit2)) {
      return await SEARCH_LIST(obj, g.P_TABLE, P_SRCBOT);
    } else {
      return true;
    }
  }
}

async function SEARCH_LIST(obj, tbl, lvl) {
  let fls = 0, nobj = 0;
  if (obj = first(obj)) {
    for (;;) {
      if (!(lvl == P_SRCBOT) && getPropAddr(obj, P.SYNONYM) && (await THIS_IT$(obj, tbl))) {
        await OBJ_FOUND(obj, tbl);
      }
      if ((!(lvl == P_SRCTOP) || hasFlag(obj, SEARCHBIT) || hasFlag(obj, SURFACEBIT)) && (nobj = first(obj))) {
        if (hasFlag(obj, OPENBIT) || hasFlag(obj, TRANSBIT) || g.P_MOBY_FLAG) {
          fls = await SEARCH_LIST(obj, tbl, hasFlag(obj, SURFACEBIT) ? P_SRCALL : (hasFlag(obj, SEARCHBIT) ? P_SRCALL : P_SRCTOP));
        }
      }
      if (obj = next(obj)) {
      } else {
        return true;
      }
    }
  } else {
    return false;
  }
}

async function OBJ_FOUND(obj, tbl) {
  let ptr = 0;
  ptr = get(tbl, g.P_MATCHLEN);
  put(tbl, ptr + 1, obj);
  return put(tbl, g.P_MATCHLEN, ptr + 1);
}

async function TAKE_CHECK() {
  return (await ITAKE_CHECK(g.P_PRSO, getb(g.P_SYNTAX, P_SLOC1))) && (await ITAKE_CHECK(g.P_PRSI, getb(g.P_SYNTAX, P_SLOC2)));
}

async function ITAKE_CHECK(tbl, ibits) {
  let ptr = 0, obj = 0, taken = 0;
  if ((ptr = get(tbl, g.P_MATCHLEN)) && (btst(ibits, SHAVE) || btst(ibits, STAKE))) {
    for (;;) {
      if ((ptr = ptr - 1) < 0) {
        return true;
      } else {
        obj = get(tbl, ptr + 1);
        if (obj == IT) {
          if (!(await ACCESSIBLE$(g.P_IT_OBJECT))) {
            tell("I don't see what you're referring to.\n");
            return false;
          } else {
            obj = g.P_IT_OBJECT;
          }
        }
        if (!(await HELD$(obj)) && !(obj == HANDS || obj == ME)) {
          g.PRSO = obj;
          if (hasFlag(obj, TRYTAKEBIT)) {
            taken = true;
          } else if (!(g.WINNER == g.PLAYER)) {
            taken = false;
          } else if (btst(ibits, STAKE) && eq(await ITAKE(false), true)) {
            taken = false;
          } else {
            taken = true;
          }
          if (taken && btst(ibits, SHAVE) && (g.WINNER == g.PLAYER)) {
            if (obj == NOT_HERE_OBJECT) {
              tell("You don't have that!\n");
              return false;
            }
            tell("You don't have ");
            if (get(tbl, g.P_MATCHLEN) > 1) {
              tell("all those things");
            } else if (obj == NOT_HERE_OBJECT) {
              tell("that");
            } else {
              tell("the ", D(obj));
              await THIS_IS_IT(obj);
            }
            tell(".\n");
            return false;
          } else if (!taken && (g.WINNER == g.PLAYER)) {
            tell("(Taken)\n");
          }
        }
      }
    }
  } else {
    return true;
  }
}

async function MANY_CHECK() {
  let loss = false, tmp = 0;
  if ((get(g.P_PRSO, g.P_MATCHLEN) > 1) && !(btst(getb(g.P_SYNTAX, P_SLOC1), SMANY))) {
    loss = 1;
  } else if ((get(g.P_PRSI, g.P_MATCHLEN) > 1) && !(btst(getb(g.P_SYNTAX, P_SLOC2), SMANY))) {
    loss = 2;
  }
  if (loss) {
    tell("You can't use multiple ");
    if (loss == 2) {
      tell("in");
    }
    tell("direct objects with \"");
    tmp = get(g.P_ITBL, P_VERBN);
    if (tmp == 0) {
      tell("tell");
    } else if (g.P_OFLAG || g.P_MERGED) {
      printB(get(tmp, 0));
    } else {
      await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
    }
    tell("\".\n");
    return false;
  } else {
    return true;
  }
}

async function ZMEMQ(itm, tbl, size = (-1)) {
  let cnt = 1;
  if (!tbl) {
    return false;
  }
  if (!(size < 0)) {
    cnt = 0;
  } else {
    size = get(tbl, 0);
  }
  for (;;) {
    if (itm == get(tbl, cnt)) {
      return tbl + (cnt * 2);
    } else if (++cnt > size) {
      return false;
    }
  }
}

async function ZMEMQB(itm, tbl, size) {
  let cnt = 0;
  for (;;) {
    if (itm == getb(tbl, cnt)) {
      return true;
    } else if (++cnt > size) {
      return false;
    }
  }
}

async function LIT$(rm, rmbit = true) {
  let ohere = 0, lit = false;
  if (g.ALWAYS_LIT && (g.WINNER == g.PLAYER)) {
    return true;
  }
  g.P_GWIMBIT = ONBIT;
  ohere = g.HERE;
  g.HERE = rm;
  if (rmbit && hasFlag(rm, ONBIT)) {
    lit = true;
  } else if (await NULL_F()) {
    return true;
  } else {
    put(g.P_MERGE, g.P_MATCHLEN, 0);
    g.P_TABLE = g.P_MERGE;
    g.P_SLOCBITS = -1;
    if (ohere == rm) {
      await DO_SL(g.WINNER, 1, 1);
      if (!(g.WINNER == g.PLAYER) && (loc(g.PLAYER) == rm)) {
        await DO_SL(g.PLAYER, 1, 1);
      }
    }
    await DO_SL(rm, 1, 1);
    if (get(g.P_TABLE, g.P_MATCHLEN) > 0) {
      lit = true;
    }
  }
  g.HERE = ohere;
  g.P_GWIMBIT = 0;
  return lit;
}

async function THIS_IT$(obj, tbl) {
  let syns = 0;
  if (hasFlag(obj, INVISIBLE)) {
    return false;
  } else if (g.P_NAM && !(await ZMEMQ(g.P_NAM, syns = getPropAddr(obj, P.SYNONYM), div(propSize(syns), 2) - 1))) {
    return false;
  } else if (g.P_ADJ && (!(syns = getPropAddr(obj, P.ADJECTIVE)) || !(await ZMEMQB(g.P_ADJ, syns, propSize(syns) - 1)))) {
    return false;
  } else if (!(g.P_GWIMBIT == 0) && !(hasFlag(obj, g.P_GWIMBIT))) {
    return false;
  }
  return true;
}

async function ACCESSIBLE$(obj) {
  let l = loc(obj);
  if (hasFlag(obj, INVISIBLE)) {
    return false;
  } else if (obj == PSEUDO_OBJECT) {
    if (g.LAST_PSEUDO_LOC == g.HERE) {
      return true;
    } else {
      return false;
    }
  } else if (!l) {
    return false;
  } else if (l == GLOBAL_OBJECTS) {
    return true;
  } else if ((l == LOCAL_GLOBALS) && (await GLOBAL_IN$(obj, g.HERE))) {
    return true;
  } else if (!(eq(await META_LOC(obj), g.HERE, loc(g.WINNER)))) {
    return false;
  } else if (l == g.WINNER || l == g.HERE || l == loc(g.WINNER)) {
    return true;
  } else if (hasFlag(l, OPENBIT) && (await ACCESSIBLE$(l))) {
    return true;
  } else {
    return false;
  }
}

async function META_LOC(obj) {
  for (;;) {
    if (!obj) {
      return false;
    } else if (loc(obj) == GLOBAL_OBJECTS) {
      return GLOBAL_OBJECTS;
    }
    if (loc(obj) == ROOMS) {
      return obj;
    } else {
      obj = loc(obj);
    }
  }
}

