async function FINISH(repeating = false) {
  crlf();
  if (!repeating) {
    await V_SCORE();
    crlf();
  }
  tell("Would you like to restart the game from the beginning, restore a saved game position, or end this session of the game? (Type RESTART, RESTORE, or QUIT):\n\n>");
  putb(g.P_INBUF, 0, 10);
  await read(g.P_INBUF, g.P_LEXV);
  putb(g.P_INBUF, 0, 60);
  if (eq(get(g.P_LEXV, 1), W.RESTAR)) {
    await restart();
    tell("Failed.\n");
    return await FINISH(true);
  } else if (eq(get(g.P_LEXV, 1), W.RESTOR)) {
    await V_RESTORE();
    return await FINISH(true);
  } else if (eq(get(g.P_LEXV, 1), W.QUIT, W.Q)) {
    return await quit();
  } else {
    return await FINISH(true);
  }
}

async function YES$() {
  restart: for (;;) {
    print(">");
    putb(g.P_INBUF, 0, 10);
    await read(g.P_INBUF, g.P_LEXV);
    putb(g.P_INBUF, 0, 60);
    if (eq(get(g.P_LEXV, 1), W.YES, W.Y)) {
      return true;
    } else if (eq(get(g.P_LEXV, 1), W.NO, W.N)) {
      return false;
    } else {
      tell("Please type YES or NO.\n\n");
      continue restart;
    }
  }
}

