async function IKILL(str) {
  if (!g.PRSO) {
    tell("There is nothing here to ", S(str), ".\n");
  } else if (!g.PRSI && (await HELD$(KNIFE))) {
    g.PRSI = KNIFE;
    tell("(with the ", D(g.PRSI), ")\n");
    await PERFORM(V.KILL, g.PRSO, g.PRSI);
    return true;
  }
  if (!(hasFlag(g.PRSO, ACTORBIT)) && !(g.PRSO == BOA || g.PRSO == HELLHOUND || g.PRSO == DORN_BEAST)) {
    tell("I've known strange people, but fighting");
    await ARTICLE(g.PRSO);
    tell("?\n");
    return true;
  } else if (!g.PRSI || (g.PRSI == HANDS)) {
    tell("Trying to ", S(str));
    await ARTICLE(g.PRSO);
    tell(" with your bare hands is suicidal.\n");
    return true;
  } else if (!(loc(g.PRSI) == PROTAGONIST)) {
    tell("You aren't even holding");
    await ARTICLE(g.PRSI, true);
    tell(".\n");
    return true;
  } else if (!(hasFlag(g.PRSI, WEAPONBIT))) {
    tell("Trying to ", S(str));
    await ARTICLE(g.PRSO, true);
    tell(" with");
    await ARTICLE(g.PRSI);
    tell(" is suicidal.\n");
    return true;
  } else {
    tell("You'd never survive the attack.\n");
    return true;
  }
}

