async function V_WALK() {
  let pt = 0, pts = 0, str = 0, obj = 0, rm = 0;
  if (!g.P_WALK_DIR) {
    await PERFORM(V.WALK_TO, g.PRSO);
    return true;
  } else if (pt = getPropAddr(g.HERE, g.PRSO)) {
    if (eq(pts = propSize(pt), UEXIT)) {
      return await GOTO(getb(pt, REXIT));
    } else if (pts == NEXIT) {
      tell(S(get(pt, NEXITSTR)), "\n");
      return M_FATAL;
    } else if (pts == FEXIT) {
      if (rm = await apply(get(pt, FEXITFCN))) {
        return await GOTO(rm);
      } else {
        if ((g.HERE == GLASS_MAZE) || (g.HERE == PARK_ENTRANCE)) {
          return false;
        } else {
          return M_FATAL;
        }
      }
    } else if (pts == CEXIT) {
      if (globalValue(getb(pt, CEXITFLAG))) {
        return await GOTO(getb(pt, REXIT));
      } else if (str = get(pt, CEXITSTR)) {
        tell(S(str), "\n");
        return M_FATAL;
      } else {
        await CANT_GO();
        return M_FATAL;
      }
    } else if (pts == DEXIT) {
      if (hasFlag(obj = getb(pt, DEXITOBJ), OPENBIT)) {
        return await GOTO(getb(pt, REXIT));
      } else if (str = get(pt, DEXITSTR)) {
        tell(S(str), "\n");
        await THIS_IS_IT(obj);
        return M_FATAL;
      } else {
        tell("The ", D(obj), " is closed.\n");
        await THIS_IS_IT(obj);
        return M_FATAL;
      }
    } else {
      return false;
    }
  } else if (g.FLYING && (g.PRSO == P.UP)) {
    tell("You're already flying as high as you can.\n");
    return M_FATAL;
  } else {
    await CANT_GO();
    return M_FATAL;
  }
}

