async function PRE_CAST() {
  let spell = 0, scroll = 0;
  if (g.PERFORMING_SPELL) {
    g.PERFORMING_SPELL = false;
    return false;
  }
  spell = isVerb(V.GNUSTO) ? GNUSTO_SPELL : (isVerb(V.FROTZ) ? FROTZ_SPELL : (isVerb(V.REZROV) ? REZROV_SPELL : (isVerb(V.IZYUK) ? IZYUK_SPELL : (isVerb(V.AIMFIZ) ? AIMFIZ_SPELL : (isVerb(V.FWEEP) ? FWEEP_SPELL : (isVerb(V.SWANZO) ? SWANZO_SPELL : (isVerb(V.GOLMAC) ? GOLMAC_SPELL : (isVerb(V.VARDIK) ? VARDIK_SPELL : (isVerb(V.PULVER) ? PULVER_SPELL : (isVerb(V.MEEF) ? MEEF_SPELL : (isVerb(V.VEZZA) ? VEZZA_SPELL : (isVerb(V.GASPAR) ? GASPAR_SPELL : (isVerb(V.YOMIN) ? YOMIN_SPELL : (isVerb(V.YONK) ? YONK_SPELL : (isVerb(V.MALYON) ? MALYON_SPELL : false)))))))))))))));
  if ((spell == g.PRSO) || (eq(loc(spell), g.PRSO) && !(eq(loc(spell), SPELL_BOOK)))) {
    tell("As you must remember from Thaumaturgy 101, you cannot cast a spell upon itself, or upon the scroll it is written on.\n");
    return true;
  } else if (hasFlag(loc(spell), MUNGBIT) && !(await ALWAYS_MEMORIZED(spell)) && eq(getProp(spell, P.COUNT), 0)) {
    tell("The spell is no longer readable.\n");
    return true;
  } else if (hasFlag(loc(spell), SCROLLBIT)) {
    scroll = loc(spell);
    if (loc(scroll) == PROTAGONIST) {
      if ((spell == YONK_SPELL) && !(await VISIBLE$(g.PRSO))) {
        return false;
      }
      move(scroll, DIAL);
      tell("As you cast the spell, the ", D(scroll), " vanishes!\n\n");
      putProp(spell, P.COUNT, 1);
    } else if (hasFlag(spell, TOUCHBIT) || (loc(scroll) == g.HERE)) {
      tell("You don't have the ", D(spell), " memorized, nor do you have the scroll on which it is written.\n");
      return true;
    } else {
      tell("The ", D(spell), " is not committed to memory, and you haven't seen any scroll on which it is written.\n");
      return true;
    }
  }
  if (g.FWEEPED) {
    tell("When you attempt to incant the ", D(spell), ", all that comes out is a high-pitched squeak!\n");
    return true;
  } else if (await ALWAYS_MEMORIZED(spell)) {
    return false;
  } else if (eq(getProp(spell, P.COUNT), 0)) {
    await THIS_IS_IT(spell);
    tell("You don't have the ", D(spell), " committed to memory!\n");
    return true;
  } else {
    putProp(spell, P.COUNT, getProp(spell, P.COUNT) - 1);
    g.SPELL_ROOM = g.SPELL_ROOM + 1;
    return false;
  }
}

