async function JIGS_UP(desc, starved = false) {
  if (desc) {
    tell(S(desc), "\n");
  }
  await FORGET_ALL();
  await KILL_INTERRUPTS();
  if (g.SLEEPING) {
    tell("\n...and a moment later you wake up in a cold sweat and realize you've been dreaming.\n");
    g.SLEEPING = false;
    clearFlag(TWISTED_FOREST, TOUCHBIT);
    clearFlag(TREE_BRANCH, TOUCHBIT);
    clearFlag(FOREST_EDGE, TOUCHBIT);
    clearFlag(MINE_FIELD, TOUCHBIT);
    clearFlag(SNAKE_PIT, TOUCHBIT);
    clearFlag(MEADOW, TOUCHBIT);
    clearFlag(RIVER_BANK, TOUCHBIT);
    clearFlag(FORT_ENTRANCE, TOUCHBIT);
    clearFlag(DRAWBRIDGE, TOUCHBIT);
    clearFlag(RUINS, TOUCHBIT);
    enable(await QUEUE(I_PARROT.id, -1));
    enable(await QUEUE(I_MAILMAN.id, 25));
    enable(await QUEUE(I_TIRED.id, 80));
    enable(await QUEUE(I_HUNGER.id, 21));
    enable(await QUEUE(I_THIRST.id, 18));
    g.LAST_SLEPT = g.MOVES;
    g.CODE_NUMBER = random(12);
    g.CURRENT_TLOC = g.CODE_NUMBER * 6;
    g.NEXT_NUMBER = get(g.NEXT_CODE_TABLE, g.CURRENT_TLOC);
    g.SCORE = g.SCORE + 5;
    move(SPELL_BOOK, PROTAGONIST);
    g.HERE = YOUR_QUARTERS;
    move(PROTAGONIST, BED);
    crlf();
    await V_VERSION();
    crlf();
    g.PRSO = false;
    g.LIT = false;
    tell("Your frotz spell seems to have worn off during the night, and it is now pitch black.\n");
    return true;
  } else {
    tell(" \n    ****  You have died  ****\n\n");
    if (g.RESURRECTION_ROOM) {
      if ((loc(SWANZO_SCROLL) == PROTAGONIST) && !(g.SWANZO_POINT == 0)) {
        move(SWANZO_SCROLL, HOLLOW);
        clearFlag(SWANZO_SCROLL, TOUCHBIT);
      }
      await ROPE_BEAM_CHECK();
      await RANDOMIZE_OBJECTS();
      await WEAR_OFF_SPELLS();
      tell("Your guardian angel, draped in white, appears floating in the nothingness before you. \"Gotten in a bit of a scrape, eh?\" he asks, writing frantically in a notebook. \"I'd love to chat, but we're so busy this month.\" ");
      if (g.RESURRECTION_ROOM == GLASS_MAZE) {
        tell("The angel looks pained. \"I hate resurrections in these stupid glass mazes! I can never tell one room from the next.\" A moment later, you appear in the maze. Unfortunately, this is one of the floor-less rooms. This time, your demise is permanent.\n");
        await FINISH();
      } else if ((g.RESURRECTION_ROOM == RIVER_BED || g.RESURRECTION_ROOM == STAGNANT_POOL || g.RESURRECTION_ROOM == TOP_OF_FALLS) && !g.RIVER_EVAPORATED) {
        tell("A moment later you find yourself at the bottom of a river, between a whirpool, some sharp rocks, and a school of river sharks. This time, your death is terminal.\n");
        await FINISH();
      } else if ((await IN_GUILD_HALL$(g.RESURRECTION_ROOM)) && hasFlag(TWISTED_FOREST, TOUCHBIT)) {
        tell("A look of consternation crosses the angel's face. \"According to the records, you're to be resurrected in your local Guild Hall. But that's quite far, and I've had a rough day. How about Egreth Castle instead, hmmm?\" Being disembodied, you find it difficult to object, and a moment later you are among the...");
        g.RESURRECTION_ROOM = RUINS;
      } else {
        tell("The angel twitches his nose, and the nothingness is replaced by...");
      }
      crlf();
      crlf();
      g.RESURRECTING = true;
      await GOTO(g.RESURRECTION_ROOM);
      if (g.RESURRECTION_ROOM == HOLLOW) {
        g.ROOM_NUMBER = 24;
        if (!g.SPLATTERED) {
          g.DORN_BEAST_WARNING = false;
          g.DORN_BEAST_ROOM = 0;
          g.LAST_DORN_ROOM = 0;
          enable(await QUEUE(I_DORN_BEAST.id, 2));
        }
      }
      if (starved) {
        tell("Unfortunately, you are still long overdue for a meal and immediately drop dead again.\n");
        await FINISH();
      }
      if (await IN_COAL_MINE$()) {
        enable(await QUEUE(I_SUFFOCATE.id, 2));
        tell("The air here is almost unbreathable.\n");
      }
      g.RESURRECTION_ROOM = false;
      g.P_CONT = false;
      return M_FATAL;
    } else {
      tell("Unfortunately, you made no provisions for your untimely death.\n");
      return await FINISH();
    }
  }
}

async function RANDOMIZE_OBJECTS() {
  let f = first(PROTAGONIST), n_ = 0;
  loop1: for (;;) {
    if (f) {
      n_ = next(f);
      if (hasFlag(f, SCROLLBIT)) {
        if (g.HERE == HAUNTED_HOUSE || g.HERE == COAL_BIN_ROOM || g.HERE == DIAL_ROOM) {
          move(f, DIAL);
        } else {
          move(f, g.HERE);
        }
      }
      f = n_;
    } else {
      break loop1;
    }
  }
  return true;
}

