async function HELD$(obj) {
  if (!obj) {
    return false;
  } else if (loc(obj) == PROTAGONIST) {
    return true;
  } else if (loc(obj) == ROOMS) {
    return false;
  } else if (loc(obj) == GLOBAL_OBJECTS) {
    return false;
  } else {
    return await HELD$(loc(obj));
  }
}

