async function FORGET_SPELL(spl) {
  let nspl = 0, f = 0, cnt = 0, tbl = 0, num = 0, sp = false;
  f = first(SPELL_BOOK);
  tbl = g.FORGET_TBL;
  loop1: for (;;) {
    if (!f) {
      break loop1;
    } else if ((cnt = getProp(f, P.COUNT)) > 0) {
      loop2: for (;;) {
        sp = f;
        put(tbl, 1, f);
        num = num + 1;
        tbl = tbl + 2;
        if ((cnt = cnt - 1) < 1) {
          break loop2;
        }
      }
    }
    f = next(f);
  }
  if ((num > 0) && eq(getProp(sp, P.COUNT), num)) {
    putProp(sp, P.COUNT, num - 1);
    return true;
  }
  put(g.FORGET_TBL, 0, num);
  if (num == 0) {
    return true;
  }
  for (;;) {
    if (!(eq(nspl = await PICK_ONE(g.FORGET_TBL), spl))) {
      putProp(nspl, P.COUNT, getProp(nspl, P.COUNT) - 1);
      return true;
    }
  }
}

async function FORGET_ALL() {
  let f = 0;
  g.SPELL_ROOM = g.SPELL_MAX;
  f = first(SPELL_BOOK);
  for (;;) {
    if (!f) {
      return true;
    } else {
      putProp(f, P.COUNT, 0);
      f = next(f);
    }
  }
}

