async function I_TIRED() {
  let forg = false;
  if (loc(PROTAGONIST) == BED) {
    tell("\nThe bed is comfortable and you are becoming tired.\n");
    g.AWAKE = g.AWAKE + 1;
    await V_SLEEP(true);
    return M_FATAL;
  }
  if (g.LOAD_ALLOWED > 10) {
    g.LOAD_ALLOWED = g.LOAD_ALLOWED - 10;
  }
  if (g.FUMBLE_NUMBER > 1) {
    g.FUMBLE_NUMBER = g.FUMBLE_NUMBER - 1;
  }
  if (g.SPELL_MAX > 1) {
    g.SPELL_MAX = g.SPELL_MAX - 1;
    if (!(g.SPELL_ROOM == 0)) {
      g.SPELL_ROOM = g.SPELL_ROOM - 1;
    }
    if (g.SPELL_ROOM == 0) {
      forg = true;
    }
  }
  enable(await QUEUE(I_TIRED.id, 8));
  g.AWAKE = g.AWAKE + 1;
  if (g.AWAKE > 8) {
    if (g.FLYING) {
      enable(await QUEUE(I_TIRED.id, 14));
      return false;
    }
    tell("\nYou drop in your tracks from exhaustion.\n\n");
    await V_SLEEP();
    return M_FATAL;
  } else {
    tell("\nYou are ", S(get(g.TIRED_TELL, g.AWAKE)));
    if (forg) {
      tell(" and the spells you've memorized are becoming confused");
    }
    tell(".\n");
    return true;
  }
}

