async function JOURNAL_F() {
  if (isVerb(V.READ, V.EXAMINE, V.LOOK_INSIDE)) {
    if (hasFlag(JOURNAL, OPENBIT)) {
      tell("You skim through the pages of the journal, a combination diary and notebook. Most of the notations, written in Belboz's familiar flowing script, deal with meetings of the Circle and business of the Guild.\n\nThere is one interesting entry toward the end of the book. Belboz refers to an ancient and evil force known simply as Jeearr, a demon whose powers could endanger the Circle and possibly the entire kingdom. He has decided to conduct some dangerous exploratory experiments, operating alone to shield the Circle from the perils involved.\n\nThe last three entries are strange and frightening -- written in a hand quite different from that of Belboz, and in a language totally unfamiliar to you.\n\nOn the inside cover is an inscription, written in a light script, which reads \"Current code: ", S(get(g.CODE_TABLE, g.CODE_NUMBER)), "\".\n");
      return true;
    } else {
      tell("It's closed and sealed with a lock.\n");
      return true;
    }
  } else if (isVerb(V.OPEN, V.UNLOCK, V.REZROV)) {
    if (hasFlag(JOURNAL, OPENBIT)) {
      tell("The journal is already open!\n");
      return true;
    } else if (isVerb(V.REZROV)) {
      tell("The journal seems to bear a spell protecting it against the simple rezrov spell.\n");
      return true;
    } else {
      if (!g.PRSI) {
        if (loc(KEY) == PROTAGONIST) {
          g.PRSI = KEY;
          tell("(with the key)\n");
        } else {
          g.PRSI = HANDS;
        }
      }
      if (g.PRSI == KEY) {
        setFlag(JOURNAL, OPENBIT);
        tell("The journal springs open.\n");
        return true;
      } else {
        tell("You can't unlock it with");
        await ARTICLE(g.PRSI);
        tell(".\n");
        return true;
      }
    }
  } else {
    return false;
  }
}

