async function VILSTU_POTION_F() {
  if (isVerb(V.EAT, V.DRINK) && !(loc(VILSTU_VIAL) == PROTAGONIST)) {
    return await POTION_POUR(VILSTU_VIAL);
  } else if (isVerb(V.RESEARCH)) {
    return await READ_ABOUT_POTIONS(3);
  } else if (isVerb(V.EAT, V.DRINK)) {
    move(VILSTU_POTION, DIAL);
    if (g.UNDER_INFLUENCE) {
      await TWO_POTIONS();
      return true;
    }
    g.UNDER_INFLUENCE = VILSTU_POTION;
    enable(await QUEUE(I_BREATHE.id, 19));
    g.VILSTUED = true;
    if (g.HERE == COAL_BIN_ROOM || g.HERE == DIAL_ROOM) {
      disable(await INT(I_SUFFOCATE.id));
      enable(await QUEUE(I_OLDER_SELF.id, 1));
    }
    tell("The orange potion tasted like pepper, and made your nose tingle.\n");
    return true;
  } else if (isVerb(V.DROP)) {
    await PERFORM(V.POUR, g.PRSO, g.PRSI);
    return true;
  } else if (isVerb(V.POUR) && (g.PRSO == VILSTU_POTION)) {
    return await POTION_POUR(VILSTU_VIAL);
  } else {
    return false;
  }
}

async function I_BREATHE() {
  g.BREATH_SHORTAGE = g.BREATH_SHORTAGE + 1;
  if (g.UNDER_INFLUENCE == VILSTU_POTION) {
    g.UNDER_INFLUENCE = false;
  }
  if (g.BREATH_SHORTAGE == 1) {
    enable(await QUEUE(I_BREATHE.id, 4));
    tell("\nYou feel the vilstu potion beginning to wear off");
    if (await IN_COAL_MINE$()) {
      tell(", and the air here seems pretty unbreathable");
    }
    tell(".\n");
    return true;
  } else if (g.BREATH_SHORTAGE == 2) {
    enable(await QUEUE(I_BREATHE.id, 6));
    tell("\nThe vilstu potion has almost completely worn off now");
    if (await IN_COAL_MINE$()) {
      tell(", and I doubt you could survive here without it");
    }
    tell(".\n");
    return true;
  } else {
    g.VILSTUED = false;
    if (g.HERE == LAGOON_FLOOR) {
      enable(await QUEUE(I_DROWN.id, -1));
    }
    tell("\nYou feel the final effects of the vilstu potion vanish");
    if (await IN_COAL_MINE$()) {
      return (await JIGS_UP(". Unfortunately, coal gas is a poor substitute for oxygen."));
    } else {
      g.AWAKE = 8;
      g.LOAD_ALLOWED = 20;
      g.FUMBLE_NUMBER = 1;
      enable(await QUEUE(I_TIRED.id, 8));
      tell(", leaving you totally exhausted (an unfortunate side effect).\n");
      return true;
    }
  }
}

