async function I_FLOOD() {
  g.RIVER_EVAPORATED = false;
  await FLOOD_LOOP(RIVER_BED);
  await FLOOD_LOOP(STAGNANT_POOL);
  await FLOOD_LOOP(TOP_OF_FALLS);
  crlf();
  if (g.HERE == STAGNANT_POOL || g.HERE == RIVER_BED || g.HERE == TOP_OF_FALLS) {
    return (await JIGS_UP("A wall of water comes rushing down the river bed! You are smashed into jelly against the rocks."));
  } else if (g.HERE == RIVER_BANK) {
    tell("A wall of water rushes down the river bed as the river returns with a vengeance.\n");
    return true;
  } else if (g.HERE == HIDDEN_CAVE) {
    tell("There is a roar of water from outside the cave. The lower part of the cave, near the mouth, fills with a pool of swirling water!\n");
    return true;
  } else {
    return false;
  }
}

async function FLOOD_LOOP(loc_) {
  let x = 0, n_ = 0;
  x = first(loc_);
  if (!x) {
    return true;
  }
  for (;;) {
    n_ = next(x);
    if (!(x == PROTAGONIST)) {
      move(x, DIAL);
    }
    if (!n_) {
      return true;
    } else {
      x = n_;
    }
  }
}

