async function GNOME_F() {
  if (GNOME == g.WINNER) {
    if (g.GNOME_SLEEPING) {
      await POOR_LISTENERS();
      return await STOP();
    } else if (isVerb(V.OPEN) && (g.PRSO == GATE)) {
      tell("\"You'll have to pay the toll first,\" explains the gnome cheerfully, \"and the toll is one zorkmid.\"\n");
      return true;
    } else {
      tell("\"Conversing with customers is disallowed by union rules.\"\n");
      return await STOP();
    }
  } else if (isVerb(V.SHAKE, V.KICK) && g.GNOME_SLEEPING) {
    await PERFORM(V.ALARM, GNOME);
    return true;
  } else if (isVerb(V.LISTEN) && g.GNOME_SLEEPING) {
    tell("The gnome snores loudly.\n");
    return true;
  } else if (isVerb(V.ALARM)) {
    if (!g.GNOME_SLEEPING) {
      tell("He's awake!\n");
      return true;
    } else if (hasFlag(GATE, OPENBIT)) {
      tell("The gnome opens one eye and looks at you. \"You again! Just go through. Let me sleep.\" He begins snoring again.\n");
      return true;
    } else if (g.GNOME_ANNOYED) {
      return (await JIGS_UP("\"You again! You've interrupted my nap for the last time! THOLL!!\" A huge troll lumbers out of the toll booth and tears you into itsy-bitsy pieces."));
    } else {
      g.GNOME_SLEEPING = false;
      enable(await QUEUE(I_GNOME.id, 2));
      tell("The gnome stirs a bit and opens one eye, which wanders around until it notices you. He jumps to his feet. \"One zorkmid, please,\" he yells with a smile.\n");
      return true;
    }
  } else if (isVerb(V.GIVE, V.ASK_ABOUT, V.ASK_FOR) && g.GNOME_SLEEPING) {
    tell("The gnome is asleep, remember?\n");
    return true;
  } else if (hasFlag(GATE, OPENBIT) && isVerb(V.SEARCH, V.LOOK_INSIDE, V.REACH_IN, V.PICK) && !g.COIN_STOLEN && !g.FWEEPED) {
    g.COIN_STOLEN = true;
    move(ZORKMID, PROTAGONIST);
    tell("You carefully search the sleeping gnome, and take the zorkmid coin you find in his pocket!\n");
    return true;
  } else if (isVerb(V.GIVE) && (g.PRSO == ZORKMID)) {
    if (hasFlag(ZORKMID, ONBIT)) {
      await GNOME_REFUSES();
      return true;
    }
    setFlag(GATE, OPENBIT);
    g.GNOME_SLEEPING = true;
    move(ZORKMID, DIAL);
    disable(await INT(I_GNOME.id));
    g.SCORE = g.SCORE + 20;
    tell("The gnome pockets the coin and opens the gate. Before you can take a step the gnome falls asleep again.\n");
    return true;
  } else if (isVerb(V.YOMIN)) {
    if (g.GNOME_SLEEPING) {
      tell("The thoughts of the sleeping gnome are focused on certain activities involving female gnomes. Embarrassed, you withdraw.\n");
      return true;
    } else {
      tell("The thoughts of the gnome seem evenly divided between getting money from you and getting back to sleep.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function GNOME_REFUSES() {
  tell("The gnome refuses, saying \"That coin is giving off light, and is therefore not legal tender.\"\n");
  return true;
}

async function I_GNOME() {
  enable(await QUEUE(I_GNOME.id, -1));
  if (g.HERE == TOLL_GATE) {
    g.PATIENCE_COUNTER = g.PATIENCE_COUNTER + 1;
    if (g.PATIENCE_COUNTER == 5) {
      g.GNOME_SLEEPING = true;
      disable(await INT(I_GNOME.id));
      g.GNOME_ANNOYED = true;
      tell("\n\"Thanks for nothing, chum,\" growls the gnome as he resumes his nap.\n");
      return true;
    } else {
      tell("\n\"Well?\" asks the gnome, tapping impatiently. \"You've interrupted my nap. Are you going to pay the toll, or not?\"\n");
      return true;
    }
  } else {
    g.GNOME_SLEEPING = true;
    g.PATIENCE_COUNTER = 3;
    disable(await INT(I_GNOME.id));
    return false;
  }
}

