async function FLAG_F() {
  if (isVerb(V.FLY)) {
    await PERFORM(V.RAISE, FLAG);
    return true;
  }
  if (g.FLAG_RAISED) {
    if (isVerb(V.RAISE)) {
      tell("It's already at the top of the pole.\n");
      return true;
    } else if (isVerb(V.LOWER)) {
      g.FLAG_RAISED = false;
      clearFlag(FLAG, TRYTAKEBIT);
      clearFlag(FLAG_POLE, NDESCBIT);
      tell("The flag is lowered to the ground.\n");
      return true;
    } else if (isVerb(V.EXAMINE)) {
      tell("You can't see it very well from here -- the flagpole is very tall.\n");
      return true;
    } else if (isVerb(V.SHAKE, V.WAVE, V.TAKE, V.MOVE, V.RUB, V.EAT, V.DRINK, V.LOOK_INSIDE)) {
      tell("The flag is ");
      if (g.FLYING) {
        tell("still ");
      }
      tell("way above you at the top of the flagpole!\n");
      return true;
    } else if (isVerb(V.LOOK_UNDER)) {
      await PERFORM(V.EXAMINE, FLAG_POLE);
      return true;
    } else {
      return false;
    }
  } else {
    if (isVerb(V.RAISE)) {
      if (g.HERE == PARADE_GROUND) {
        setFlag(FLAG, TRYTAKEBIT);
        move(FLAG, g.HERE);
        setFlag(FLAG_POLE, NDESCBIT);
        g.FLAG_RAISED = true;
        tell("The flag is raised to the top of the pole.\n");
        return true;
      } else {
        tell("There's no flagpole in sight.\n");
        return true;
      }
    } else if (isVerb(V.LOWER)) {
      tell("You've already done that.\n");
      return true;
    } else if (isVerb(V.WAVE)) {
      tell("How patriotic!\n");
      return true;
    } else if (isVerb(V.WEAR)) {
      tell("Who do you think you are, Abbie Hoffman?\n");
      return true;
    } else if (isVerb(V.EXAMINE, V.LOOK_INSIDE, V.SHAKE, V.RUB, V.SEARCH) && !g.FOOBLE_FOUND) {
      g.FOOBLE_FOUND = true;
      move(FOOBLE_VIAL, g.HERE);
      await THIS_IS_IT(FOOBLE_VIAL);
      tell("As you fiddle with the flag, an aqua vial drops from a hidden pocket and falls to the ground.\n");
      return true;
    } else if (isVerb(V.EXAMINE)) {
      tell("The tattered flag displays the brown and gold of ancient Quendor.\n");
      return true;
    } else {
      return false;
    }
  }
}

