async function START_RIDE(loc_) {
  let x = 0, n_ = 0;
  g.RIDE_IN_PROGRESS = true;
  x = first(loc_);
  for (;;) {
    n_ = next(x);
    if (!(x == PROTAGONIST || x == CAR || x == LOG_BOAT)) {
      setFlag(x, INVISIBLE);
    }
    if (!n_) {
      return true;
    } else {
      x = n_;
    }
  }
}

async function END_RIDE() {
  let x = 0, n_ = 0;
  g.RIDE_IN_PROGRESS = false;
  g.RIDE_COUNTER = 0;
  disable(await INT(I_FLUME_TRIP.id));
  disable(await INT(I_ROLLER_COASTER_TRIP.id));
  x = first(FLUME);
  loop1: for (;;) {
    n_ = next(x);
    clearFlag(x, INVISIBLE);
    if (!n_) {
      break loop1;
    } else {
      x = n_;
    }
  }
  x = first(ROLLER_COASTER);
  for (;;) {
    n_ = next(x);
    clearFlag(x, INVISIBLE);
    if (!n_) {
      return true;
    } else {
      x = n_;
    }
  }
}

