async function RADAR_VIEW() {
  let x = 0, count = 0, lup = 0, ldown = 0, north = 0, south = 0, east = 0, west = 0;
  x = false;
  lup = false;
  ldown = false;
  north = false;
  south = false;
  east = false;
  west = false;
  count = 0;
  tell(" Thanks to your sonar-like bat senses, you can tell that there are surfaces ");
  if ((g.MAZE_CROSSED && eq(get(g.POST_UP_EXITS, g.ROOM_NUMBER), 0)) || (!g.MAZE_CROSSED && eq(get(g.PRE_UP_EXITS, g.ROOM_NUMBER), 0))) {
    lup = true;
    count = count + 1;
  }
  if ((g.MAZE_CROSSED && eq(get(g.POST_DOWN_EXITS, g.ROOM_NUMBER), 0)) || (!g.MAZE_CROSSED && eq(get(g.PRE_DOWN_EXITS, g.ROOM_NUMBER), 0))) {
    ldown = true;
    count = count + 1;
  }
  if ((g.MAZE_CROSSED && eq(get(g.POST_NORTH_EXITS, g.ROOM_NUMBER), 0)) || (!g.MAZE_CROSSED && eq(get(g.PRE_NORTH_EXITS, g.ROOM_NUMBER), 0))) {
    north = true;
    count = count + 1;
  }
  if ((g.MAZE_CROSSED && eq(get(g.POST_SOUTH_EXITS, g.ROOM_NUMBER), 0)) || (!g.MAZE_CROSSED && eq(get(g.PRE_SOUTH_EXITS, g.ROOM_NUMBER), 0))) {
    south = true;
    count = count + 1;
  }
  if ((g.MAZE_CROSSED && eq(get(g.POST_EAST_EXITS, g.ROOM_NUMBER), 0)) || (!g.MAZE_CROSSED && eq(get(g.PRE_EAST_EXITS, g.ROOM_NUMBER), 0))) {
    east = true;
    count = count + 1;
  }
  if ((g.MAZE_CROSSED && eq(get(g.POST_WEST_EXITS, g.ROOM_NUMBER), 0)) || (!g.MAZE_CROSSED && eq(get(g.PRE_WEST_EXITS, g.ROOM_NUMBER), 0))) {
    west = true;
    count = count + 1;
  }
  if (lup) {
    if (count == 1) {
      tell(" and ");
    } else if (x) {
      tell(", ");
    }
    x = true;
    count = count - 1;
    tell("above you");
  }
  if (ldown) {
    if (count == 1) {
      tell(" and ");
    } else if (x) {
      tell(", ");
    }
    x = true;
    count = count - 1;
    tell("below you");
  }
  if (north) {
    if (count == 1) {
      tell(" and ");
    } else if (x) {
      tell(", ");
    }
    x = true;
    count = count - 1;
    tell("to the north");
  }
  if (south) {
    if (count == 1) {
      tell(" and ");
    } else if (x) {
      tell(", ");
    }
    x = true;
    count = count - 1;
    tell("to the south");
  }
  if (east) {
    if (count == 1) {
      tell(" and ");
    } else if (x) {
      tell(", ");
    }
    x = true;
    count = count - 1;
    tell("to the east");
  }
  if (west) {
    if (count == 1) {
      tell(" and ");
    } else if (x) {
      tell(", ");
    }
    x = true;
    count = count - 1;
    tell("to the west");
  }
  tell(".");
  return true;
}

