async function MAZE_TO_TABLE(loc_) {
  let cnt = 0, f = first(GLASS_MAZE), n_ = 0;
  for (;;) {
    if (f) {
      n_ = next(f);
    } else {
      return true;
    }
    if (f == g.WINNER) {
    } else if (hasFlag(f, TAKEBIT) || (f == DORN_BEAST_CORPSE)) {
      loop2: for (;;) {
        if (eq(get(g.MAZE_TABLE, cnt), 0)) {
          put(g.MAZE_TABLE, cnt, loc_);
          put(g.MAZE_TABLE, cnt + 1, f);
          cnt = cnt + 2;
          move(f, DIAL);
          break loop2;
        } else {
          cnt = cnt + 2;
        }
      }
    }
    f = n_;
  }
}

async function TABLE_TO_MAZE(loc_) {
  let table = g.MAZE_TABLE, cnt = 0;
  for (;;) {
    if (!(cnt < MAZE_TABLE_LENGTH)) {
      return true;
    } else if (eq(get(g.MAZE_TABLE, cnt), loc_)) {
      put(g.MAZE_TABLE, cnt, 0);
      move(get(g.MAZE_TABLE, cnt + 1), GLASS_MAZE);
    }
    cnt = cnt + 2;
  }
}

async function DROP_IN_MAZE() {
  let cnt = 0, new_room = 0;
  if (g.MAZE_CROSSED) {
    if (g.ROOM_NUMBER == 12) {
      new_room = 3;
    } else if (g.ROOM_NUMBER == 13) {
      new_room = 4;
    } else if (g.ROOM_NUMBER == 16) {
      new_room = 7;
    } else if (g.ROOM_NUMBER == 18) {
      new_room = 9;
    } else if (g.ROOM_NUMBER == 19) {
      new_room = 10;
    } else if (g.ROOM_NUMBER == 20) {
      new_room = 11;
    } else if (g.ROOM_NUMBER == 25) {
      new_room = 7;
    } else if (g.ROOM_NUMBER == 27) {
      new_room = 9;
    }
  } else {
    if (g.ROOM_NUMBER == 10) {
      new_room = 1;
    } else if (g.ROOM_NUMBER == 12) {
      new_room = 3;
    } else if (g.ROOM_NUMBER == 16) {
      new_room = 7;
    } else if (g.ROOM_NUMBER == 20) {
      new_room = 11;
    } else if (g.ROOM_NUMBER == 21) {
      new_room = 3;
    } else if (g.ROOM_NUMBER == 26) {
      new_room = 17;
    }
  }
  if (new_room == 0) {
    tell("Bug #14\n");
    return true;
  }
  for (;;) {
    if (eq(get(g.MAZE_TABLE, cnt), 0)) {
      put(g.MAZE_TABLE, cnt, new_room);
      put(g.MAZE_TABLE, cnt + 1, g.PRSO);
      cnt = cnt + 2;
      return true;
    } else {
      cnt = cnt + 2;
    }
  }
}

async function REARRANGE_MAZE_TABLE() {
  let cnt = 0;
  for (;;) {
    if (!(cnt < MAZE_TABLE_LENGTH)) {
      return true;
    } else if (eq(get(g.MAZE_TABLE, cnt), 12)) {
      put(g.MAZE_TABLE, cnt, 3);
    } else if (eq(get(g.MAZE_TABLE, cnt), 13)) {
      put(g.MAZE_TABLE, cnt, 4);
    } else if (eq(get(g.MAZE_TABLE, cnt), 16)) {
      put(g.MAZE_TABLE, cnt, 7);
    } else if (eq(get(g.MAZE_TABLE, cnt), 18)) {
      put(g.MAZE_TABLE, cnt, 9);
    } else if (eq(get(g.MAZE_TABLE, cnt), 19)) {
      put(g.MAZE_TABLE, cnt, 10);
    } else if (eq(get(g.MAZE_TABLE, cnt), 20)) {
      put(g.MAZE_TABLE, cnt, 11);
    } else if (eq(get(g.MAZE_TABLE, cnt), 25)) {
      put(g.MAZE_TABLE, cnt, 7);
    } else if (eq(get(g.MAZE_TABLE, cnt), 27)) {
      put(g.MAZE_TABLE, cnt, 9);
    }
    cnt = cnt + 2;
  }
}

