async function I_DORN_BEAST() {
  enable(await QUEUE(I_DORN_BEAST.id, -1));
  if (g.HERE == HOLLOW) {
    if (g.DORN_BEAST_WARNING) {
      return await DORN_DEATH();
    } else {
      move(DORN_BEAST, g.HERE);
      g.DORN_BEAST_WARNING = true;
      tell("\nWith a loud roar, a dreadfully huge dorn beast emerges from the shadows at the base of the cliff and gallops toward you.\n");
      return true;
    }
  } else {
    setFlag(DORN_BEAST, NDESCBIT);
    if (!g.DORN_BEAST_WARNING) {
      g.DORN_BEAST_WARNING = true;
      tell("\nFrom outside the maze, you hear the bellowing of a ferocious dorn beast!\n");
      return true;
    } else if (g.ROOM_NUMBER == g.DORN_BEAST_ROOM || g.ROOM_NUMBER == g.LAST_DORN_ROOM) {
      crlf();
      return await DORN_DEATH();
    } else {
      tell("\nThe dorn beast rushes after you. Its ear-splitting bellowing resounds throughout the glass maze.");
      if (g.ROOM_NUMBER == 27) {
        g.SPLATTERED = true;
        disable(await INT(I_DORN_BEAST.id));
        move(DORN_BEAST, DIAL);
        put(g.MAZE_TABLE, 38, 9);
        put(g.MAZE_TABLE, 39, DORN_BEAST_CORPSE);
        tell(" Suddenly, the dorn-beast realizes that it is galloping through midair, and gives a surprisingly high-pitched squeal. It claws frantically at thin air, trying desperately to invent dorn beast flight. You happily notice that dorn beasts do not so much fly as plummet.");
      } else {
        g.LAST_DORN_ROOM = g.DORN_BEAST_ROOM;
        g.DORN_BEAST_ROOM = g.ROOM_NUMBER;
        move(DORN_BEAST, g.HERE);
      }
      return crlf();
    }
  }
}

