async function COVE_F(rarg) {
  let x = false;
  if ((rarg == M_ENTER) && !(hasFlag(COVE, TOUCHBIT))) {
    if (g.BOOK_BELONGS_IN_LAGOON) {
      move(SPELL_BOOK, LAGOON_FLOOR);
    }
    put(g.VEZZAS, 6, 0);
    g.SCORE = g.SCORE + 20;
    disable(await INT(I_SUFFOCATE.id));
    disable(await INT(I_YOUNGER_SELF.id));
    disable(await INT(I_OLDER_SELF.id));
    if (g.GOLMACKED && !g.COMBO_REVEALED) {
      await POOF();
    } else if (!g.GOLMACKED) {
      if (await HELD$(ROPE)) {
        move(ROPE, DIAL);
        x = true;
      }
      if (await HELD$(BEAM)) {
        move(BEAM, DIAL);
        x = true;
      }
      if (await HELD$(VARDIK_SCROLL)) {
        move(VARDIK_SCROLL, DIAL);
        x = true;
      }
      if (await HELD$(GOLMAC_SCROLL)) {
        move(GOLMAC_SCROLL, DIAL);
        x = true;
      }
      if (x) {
        tell("As you slide down the chute, some of your possessions suddenly vanish! ");
      }
    }
    tell("You fly out of the chute and land just at the edge of some water...\n\n");
    return true;
  } else {
    return false;
  }
}

async function POOF() {
  g.POOFED = true;
  tell("Suddenly, without the slightest fanfare, you cease to exist!\n");
  return await FINISH();
}

async function OCEAN_SHORE_F(rarg) {
  if (rarg == M_LOOK) {
    tell("You are ");
    if (g.FLYING) {
      tell("floating above");
    } else {
      tell("standing on");
    }
    tell(" the western shore of the mighty Flathead Ocean. According to legends you read at the University, the eastern shore of this ocean is a strange land of magical beings and priceless treasures. ");
    if (g.HERE == OCEAN_NORTH) {
      tell("You could go north along the shore; the edge of a small cove lies to the southwest.");
    } else {
      tell("The beach to the south is blocked by a tall cliff; a lagoon shore lies to the northwest.");
    }
    return crlf();
  } else {
    return false;
  }
}

async function OCEAN_F() {
  let x = 0;
  if (g.HERE == GUN_EMPLACEMENT || g.HERE == TURRET || g.HERE == TOP_OF_FALLS) {
    tell("The ocean lies far below you.\n");
    return true;
  } else if (isVerb(V.PULVER)) {
    g.PERFORMING_SPELL = true;
    await PERFORM(V.PULVER, LAGOON_OBJECT);
    return true;
  } else if (isVerb(V.DRINK, V.DRINK_FROM)) {
    await PERFORM(V.DRINK, WATER);
    return true;
  } else if (isVerb(V.EXAMINE)) {
    tell("It streches east as far as the eye can see.\n");
    return true;
  } else if (isVerb(V.RESEARCH)) {
    tell("The Flathead Ocean, called the Great Sea by the ancients, has a very unusual feature -- its western shore basks in the sunlight while its eastern shore lies far underground.\n");
    return true;
  } else if (isVerb(V.PUT) && (OCEAN == g.PRSI)) {
    move(g.PRSO, DIAL);
    return await SPLASH();
  } else if (isVerb(V.THROUGH)) {
    return (await JIGS_UP("Certain death."));
  } else {
    return false;
  }
}

async function CLIFF_PSEUDO() {
  if (isVerb(V.CLIMB_UP, V.CLIMB_FOO)) {
    if (g.FLYING) {
      tell("The cliff is too high to fly over.\n");
      return true;
    } else {
      tell("The cliff is unclimbable.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function LAGOON_OBJECT_F() {
  if (isVerb(V.THROUGH)) {
    if (g.HERE == LAGOON || g.HERE == LAGOON_FLOOR) {
      return await LOOK_AROUND_YOU();
    } else {
      return await GOTO(LAGOON);
    }
  } else if (isVerb(V.PUT) && !(g.HERE == LAGOON_FLOOR) && (g.PRSI == LAGOON_OBJECT)) {
    move(g.PRSO, LAGOON_FLOOR);
    if (hasFlag(g.PRSO, SCROLLBIT) || (g.PRSO == SPELL_BOOK)) {
      setFlag(g.PRSO, MUNGBIT);
    }
    return await SPLASH();
  } else if (isVerb(V.EXAMINE)) {
    tell("The water looks calm and hospitable.\n");
    return true;
  } else if (isVerb(V.DRINK, V.DRINK_FROM)) {
    await PERFORM(V.DRINK, WATER);
    return true;
  } else if (isVerb(V.PULVER)) {
    tell("The water level seems to drop an inch or two, for a moment.\n");
    return true;
  } else {
    return false;
  }
}

async function LAGOON_F(rarg) {
  let x = 0;
  if (rarg == M_ENTER) {
    x = first(PROTAGONIST);
    for (;;) {
      if (x) {
        if (hasFlag(x, SCROLLBIT) || (x == SPELL_BOOK)) {
          setFlag(x, MUNGBIT);
        }
        x = next(x);
      } else {
        return true;
      }
    }
  } else if (rarg == M_LOOK) {
    tell("You are ");
    if (g.FLYING) {
      tell("flying over");
    } else {
      tell("swimming on");
    }
    tell(" the surface of a calm lagoon, whose sandy floor is visible below. A curved beach surrounds this inlet on its western side.\n");
    return true;
  } else {
    return false;
  }
}

async function LAGOON_FLOOR_ENTER_F() {
  if (g.FLYING) {
    await WHILE_FLYING();
    return false;
  } else {
    return LAGOON_FLOOR;
  }
}

async function SAND_PSEUDO() {
  if (PSEUDO_OBJECT == g.PRSO) {
    g.PERFORMING_SPELL = true;
    await PERFORM(g.PRSA, GROUND, g.PRSI);
    return true;
  } else {
    g.PERFORMING_SPELL = true;
    await PERFORM(g.PRSA, g.PRSO, GROUND);
    return true;
  }
}

async function LAGOON_FLOOR_F(rarg) {
  if (rarg == M_ENTER) {
    enable(await QUEUE(I_DROWN.id, -1));
    return false;
  } else {
    return false;
  }
}

async function I_DROWN() {
  if (g.HERE == LAGOON_FLOOR) {
    if (g.VILSTUED) {
      return false;
    }
    g.UNDERWATER_COUNTER = g.UNDERWATER_COUNTER + 1;
    if (g.UNDERWATER_COUNTER == 3) {
      tell("\nYou won't be able to hold your breath much longer.\n");
      return true;
    } else if (g.UNDERWATER_COUNTER == 4) {
      tell("\nBetter get some fresh air soon!\n");
      return true;
    } else if (g.UNDERWATER_COUNTER == 5) {
      g.UNDERWATER_COUNTER = 0;
      crlf();
      return (await JIGS_UP("You run out of air and drown."));
    } else {
      return false;
    }
  } else {
    g.UNDERWATER_COUNTER = 0;
    disable(await INT(I_DROWN.id));
    return false;
  }
}

async function CORAL_PSEUDO() {
  if (isVerb(V.EXAMINE) && (loc(g.HERE) == SPENSEWEEDS)) {
    tell("The coral is covered by swaying spenseweeds.\n");
    return true;
  } else {
    return false;
  }
}

async function SPENSEWEEDS_F() {
  if (isVerb(V.MEEF)) {
    move(SPENSEWEEDS, DIAL);
    move(CRATE, g.HERE);
    await THIS_IS_IT(CRATE);
    tell("The spenseweeds wilt away, revealing a wooden crate labelled with black lettering.\n");
    return true;
  } else if (isVerb(V.LOOK_UNDER)) {
    tell("That's difficult -- they're well rooted in the coral.\n");
    return true;
  } else {
    return false;
  }
}

async function CRATE_F() {
  if (isVerb(V.OPEN, V.REZROV) && !g.CRATE_POINT) {
    g.CRATE_POINT = true;
    g.SCORE = g.SCORE + 15;
    return false;
  } else if (isVerb(V.READ)) {
    await FIXED_FONT_ON();
    tell("Stencilled diagonally across the crate:\n\n    GRUE PROTECTION KIT\n\nBelow, in much smaller letters:\n\n    FROM:\n    Frobozz Magic Grue Accessories Co.\n\n    TO:\n    Aragain Brothers Circus\n    Attn: Grue Trainer\n");
    return await FIXED_FONT_OFF();
  } else {
    return false;
  }
}

async function BRASS_LANTERN_F() {
  if (isVerb(V.EXAMINE)) {
    tell("It is a battery-powered lantern like those used by adventurers and explorers. It is currently ");
    if (hasFlag(BRASS_LANTERN, ONBIT)) {
      tell("on");
    } else {
      tell("off");
    }
    tell(".\n");
    return true;
  } else {
    return false;
  }
}

async function GRUE_REPELLENT_F() {
  if (isVerb(V.SHAKE)) {
    if (g.SPRAY_USED$) {
      tell("The can seems empty.\n");
      return true;
    } else {
      tell("There is a sloshing sound from inside.\n");
      return true;
    }
  } else if (isVerb(V.SPRAY, V.PUT_ON) && (g.PRSO == GRUE_REPELLENT)) {
    if (g.SPRAY_USED$) {
      tell("The repellent is all gone.\n");
      return true;
    } else if (!g.PRSI) {
      g.SPRAY_USED$ = true;
      tell("The spray stinks amazingly for a few moments, then drifts away.\n");
      return true;
    } else {
      if (g.PRSI == ME) {
        enable(await QUEUE(I_SPRAY.id, 5));
        g.SPRAYED$ = true;
      }
      g.SPRAY_USED$ = true;
      tell("The spray smells like a mixture of old socks and burning rubber. If I were a grue I'd sure stay clear!\n");
      return true;
    }
  } else {
    return false;
  }
}

async function I_SPRAY() {
  g.SPRAYED$ = false;
  tell("\nThat horrible smell is much less pungent now.\n");
  return true;
}

async function MOUTH_OF_RIVER_F(rarg) {
  if (rarg == M_LOOK) {
    tell("A mighty river spills into the ocean here. Looking up the river valley, you see a tall waterfall. Atop a cliff, high above you, is the rampart of a fortress. A cave entrance ");
    if (loc(VINES) == g.HERE) {
      tell("at the base of the cliff to the west is blocked by writhing green vines");
    } else {
      tell("lies to the west");
    }
    tell(".\n");
    return true;
  } else if ((rarg == M_END) && (loc(VINES) == g.HERE) && prob(15)) {
    crlf();
    tell("Suddenly you realize that, without really thinking about it, you were ");
    if (g.FLYING) {
      tell("flying");
    } else {
      tell("walking");
    }
    tell(" toward the wriggling vines. As you stop, a feeling of annoyance seems to radiate from the plants.\n");
    return true;
  } else {
    return false;
  }
}

async function VINES_F() {
  if (isVerb(V.MEEF)) {
    move(VINES, DIAL);
    tell("You can almost feel a wave of pain from the vines as they shrivel away.\n");
    return true;
  } else if (isVerb(V.ATTACK, V.KILL)) {
    return (await JIGS_UP("Your attack is somewhat quixotic as the vines wrap around and tear you to pieces."));
  } else if (isVerb(V.THROUGH, V.KICK, V.BITE, V.TAKE, V.CLIMB_UP, V.CLIMB_FOO, V.PUSH, V.MOVE, V.RUB)) {
    return await DO_WALK(P.WEST);
  } else {
    return false;
  }
}

async function VINES_EXIT_F() {
  if (loc(VINES) == g.HERE) {
    (await JIGS_UP("The vines encircle you and tear you limb from limb."));
    return false;
  } else {
    return GRUE_LAIR;
  }
}

async function GRUE_LAIR_F(rarg) {
  if (!g.SPRAYED$ && (rarg == M_END) && !(loc(GRUE_SUIT) == PROTAGONIST)) {
    if (g.LIT || g.BLORTED) {
      return (await JIGS_UP("The grues lurk toward you! Your last sight is a hundred slavering fangs."));
    } else {
      return (await JIGS_UP("Suddenly, you are set upon by countless slavering fangs!"));
    }
  } else {
    return false;
  }
}

async function MUTATED_GRUES_F() {
  if (isVerb(V.FROTZ)) {
    tell("One of the grues gives off a flash of light but, strangely, it doesn't seem to notice or care.\n");
    return true;
  } else if (isVerb(V.RESEARCH)) {
    await PERFORM(V.RESEARCH, GRUE);
    return true;
  } else {
    return false;
  }
}

async function MUTATED_GRUES_DESCFCN(rarg) {
  if (g.LIT || g.BLORTED) {
    if (g.SPRAYED$) {
      await LIT_MESSAGE();
      tell("They stagger about the room, covering their noses and making horrid gurgling noises.\n");
      return true;
    } else if (loc(GRUE_SUIT) == PROTAGONIST) {
      await LIT_MESSAGE();
      tell("They seem to be ignoring you, aside from a few suspicious gurgles in your direction.\n");
      return true;
    } else {
      await LIT_MESSAGE();
      tell("Baring tremendous fangs, they form a circle around you...\n");
      return true;
    }
  } else {
    tell("There are terrifying gurgling noises from the darkness!\n");
    return true;
  }
}

async function LIT_MESSAGE() {
  tell("A pack of grues fills the room! ");
  if (g.LIT) {
    tell("The grues, contrary to all conventional wisdom, aren't bothered by your light in the least. They must be mutated grues, no longer fearing light! ");
    return true;
  } else {
    return false;
  }
}

async function MAMMOTH_CAVERN_F(rarg) {
  if (rarg == M_ENTER) {
    g.SCORE = g.SCORE + g.CAVERN_POINT;
    g.CAVERN_POINT = 0;
    return put(g.VEZZAS, 7, 0);
  } else {
    return false;
  }
}

async function MACHINERY_F() {
  if (isVerb(V.MUNG, V.LAMP_ON)) {
    return (await JIGS_UP("A field of energy leaps forth, reducing you to a pile of smoldering ash."));
  } else if (isVerb(V.EXAMINE, V.READ)) {
    tell("You notice, on one machine, a tiny plaque which reads:\n\nFROBOZZ MAGIC MUTATED GRUE BREEDER CO.\n");
    return true;
  } else {
    return false;
  }
}

async function CHAMBER_OF_LIVING_DEATH_F(rarg) {
  if ((rarg == M_BEG) && !(isVerb(V.QUIT, V.SAVE, V.VERSION)) && !(isVerb(V.RESTORE, V.RESTART)) && !(isVerb(V.BRIEF, V.VERBOSE, V.SUPER_BRIEF)) && !(isVerb(V.SCRIPT, V.UNSCRIPT))) {
    await AGONY();
    return true;
  } else if (rarg == M_END) {
    tell("Hideous parasites descend upon you and tear the flesh from your bones, gnaw the eyes from your sockets, and feast upon your very brain tissue. Amazingly, you do not die, and your body regenerates itself as you await the next attack...\n");
    return true;
  } else {
    return false;
  }
}

async function PARASITES_PSEUDO() {
  return false;
}

async function HALL_OF_ETERNAL_DEATH_F(rarg) {
  if ((rarg == M_BEG) && !(isVerb(V.QUIT, V.SAVE, V.VERSION)) && !(isVerb(V.RESTORE, V.RESTART)) && !(isVerb(V.BRIEF, V.VERBOSE, V.SUPER_BRIEF)) && !(isVerb(V.SCRIPT, V.UNSCRIPT))) {
    await AGONY();
    return true;
  } else if (rarg == M_END) {
    tell("Disembodied forces suck the very thoughts from your mind, savoring each moment and growing stronger. Every second is an agonizing torment, as though thousands of raging fires were exploding in your skull, filling you with a pain greater than you could ever imagine.\n");
    return true;
  } else {
    return false;
  }
}

async function FORCE_PSEUDO() {
  return false;
}

async function AGONY() {
  tell("Your agony is too great to concentrate on such an action.\n");
  return true;
}

async function BLACK_DOOR_F() {
  if (isVerb(V.OPEN, V.REZROV)) {
    tell("As the door opens, hundreds of slime-covered tentacles stream out and drag you across the threshold...\n\n");
    await ROB(PROTAGONIST);
    disable(await INT(I_TIRED.id));
    disable(await INT(I_THIRST.id));
    disable(await INT(I_HUNGER.id));
    await WEAR_OFF_SPELLS();
    return await GOTO(CHAMBER_OF_LIVING_DEATH);
  } else {
    return false;
  }
}

async function SILVER_DOOR_F() {
  if (isVerb(V.OPEN, V.REZROV)) {
    tell("The door blows open, knocking you to the ground. You are pulled through the open doorway by an unseen force...\n\n");
    await ROB(PROTAGONIST);
    disable(await INT(I_TIRED.id));
    disable(await INT(I_HUNGER.id));
    disable(await INT(I_THIRST.id));
    await WEAR_OFF_SPELLS();
    return await GOTO(HALL_OF_ETERNAL_PAIN);
  } else {
    return false;
  }
}

async function WHITE_DOOR_F() {
  if (isVerb(V.OPEN, V.REZROV)) {
    if (g.HERE == BELBOZ_HIDEOUT) {
      await DO_WALK(P.EAST);
      return true;
    }
    g.SCORE = g.SCORE + g.WHITE_DOOR_SCORE;
    g.WHITE_DOOR_SCORE = 0;
    tell("The door creaks slowly open. Within, you see someone lying as though asleep. You feel yourself drawn into the room...\n\n");
    enable(await QUEUE(I_BELBOZ_AWAKES.id, 8));
    return await GOTO(BELBOZ_HIDEOUT);
  } else {
    return false;
  }
}

async function I_UNVARDIK() {
  g.VARDIKED = false;
  tell("\nYour head feels numb for a moment, and your mind feels suddenly open and unprotected.\n");
  return true;
}

async function KILL_BELBOZ() {
  if (g.BELBOZ_GASPARED) {
    g.BELBOZ_GASPARED = false;
    tell("As you stab Belboz, an apparition rises from his body. Floating above him like a cloud of fog, it howls with laughter. A moment later, gaspar begins to heal the wounds, and the spirit flows back into the body.\n");
    crlf();
    return await I_BELBOZ_AWAKES();
  } else {
    tell("You stab the knife time and again into Belboz, who writhes in pain, eyes bulging outward. Sickened and dizzy, you stagger back.\n\n");
    g.BELBOZ_DEAD = true;
    return await SWANZO_BELBOZ();
  }
}

async function SWANZO_BELBOZ() {
  tell("A wispy translucent shape rises from the ");
  if (g.BELBOZ_DEAD) {
    tell("corpse");
  } else {
    tell("body");
  }
  tell(" of Belboz. It speaks in a voice so deep that your whole body seems to hear it. \"Foolish Charlatan! I am forced to flee that weak, old body -- I shall take your own, instead! Already I have sucked all knowledge, all secrets from that ancient Enchanter. Now begins an epoch of evil transcending even your worst nightmares; a reign of terror that will last a thousand thousand years!\" The shape blows toward you on a cold wind.\n\n");
  if (g.VARDIKED) {
    tell("Jeearr surrounds you like a cloud and begins to contract. Suddenly, it strikes your invisible protection and recoils as if burned. \"No!\" it cries. \"Such a guileless Enchanter developing a mind shield?\" The cloud is thinner, the voice fainter. \"It cannot be! I cannot survive ... without a host.\" The demon roils in agony, then thins and dissipates. There is a final scream of pain, then silence.\n\n");
    if (g.BELBOZ_DEAD) {
      tell("Jeearr is vanquished; the kingdom is saved. But you - you are stranded in a land unknown, and your closest friend, the greatest Enchanter of his age, lies dead by your own hand. Kneeling by his blood-soaked corpse, you beg for another chance...\n");
      return await FINISH();
    } else {
      tell("Belboz moans softly, and begins stirring. He sees you and rises, instantly alert. After posing a few well-chosen questions, he casts a brief but unfamiliar spell.\n\nAn instant later, ");
      if (loc(GRUE_SUIT) == PROTAGONIST) {
        tell("your grue suit has vanished and ");
      }
      tell("you are standing in the Chamber of the Circle. The Circle of Enchanters is assembled. Belboz speaks. \"Once again, this young Enchanter has done a matchless service to the Guild and to the entire kingdom, displaying resourcefulness and imagination worthy of the greatest of Enchanters. I grow old, and must soon step down as Head of the Circle. But let it be known that a successor has been found.\"\n\n");
      g.SCORE = g.SCORE + 25;
      g.HERE = CHAMBER_OF_THE_CIRCLE;
      await V_SCORE();
      tell("\nHere ends the second chapter of the Enchanter saga, in which, by virtue of your skills, you have been appointed as the next leader of the Circle of Enchanters. The final adventure awaits you as the Enchanter series concludes.\n");
      if (!(loc(MORGIA_PLANT) == BELBOZ_QUARTERS)) {
        tell("\nYou hear a distant bellow. \"What happened to my morgia plant?\"\n");
      }
      return await FINISH(true);
    }
  } else {
    tell("You feel an overwhelming sense of oppression as the demon seizes control of your mind and body. The monster reaches into the recesses of your mind, adding your hard-earned magic powers to its own. As it settles comfortably into your skull, the demon grants you a vision of the future. You see the enslaved people of the land toiling to erect great idols to Jeearr. Parents offer up their own children upon these altars, as the rivers of the land fill with blood. And YOU embody Jeearr; you are cursed by ten thousand generations of victims; your face adorns the idols. And worst of all, you remain awake and aware, a witness to horror, never sleeping, and never, ever to escape.\n");
    g.SCORE = -99;
    return await FINISH();
  }
}

async function I_BELBOZ_AWAKES() {
  if (!(g.HERE == BELBOZ_HIDEOUT)) {
    return false;
  }
  tell("\nSuddenly, Belboz's eyes flicker and he leaps to his feet. His face is unrecognizable, a twisted mask of hatred. \"Meddlesome Enchanter! I should have killed you all before I left! But better late than never...\" Lightning bolts flash toward you from his fingers, but rather than dying, you find yourself in the...\n\n");
  await ROB(PROTAGONIST);
  disable(await INT(I_TIRED.id));
  disable(await INT(I_THIRST.id));
  disable(await INT(I_HUNGER.id));
  await WEAR_OFF_SPELLS();
  return await GOTO(HALL_OF_ETERNAL_PAIN);
}

